# -*- coding: utf-8 -*-
"""JingniFlow 统一异常体系。"""


class JingniError(Exception):
    """所有 JingniFlow 异常的基类。"""

    code = "JINGNI_ERROR"
    platform = None

    def __init__(self, message, code=None, platform=None, details=None):
        Exception.__init__(self, message)
        self.message = message
        if code is not None:
            self.code = code
        if platform is not None:
            self.platform = platform
        self.details = details or {}

    def __str__(self):
        if self.platform:
            return "[{0}:{1}] {2}".format(self.code, self.platform, self.message)
        return "[{0}] {1}".format(self.code, self.message)


class ValidationError(JingniError):
    code = "JINGNI_VALIDATION"


class UnsupportedFeature(JingniError):
    code = "JINGNI_UNSUPPORTED"

    def __init__(self, platform, feature, message=None):
        if message is None:
            message = "platform {0} does not support feature {1}".format(
                platform, feature
            )
        JingniError.__init__(
            self,
            message,
            code=self.code,
            platform=platform,
            details={"feature": feature},
        )
        self.feature = feature


class PlatformApiMissing(JingniError):
    code = "JINGNI_PLATFORM_API_MISSING"


class DataError(JingniError):
    code = "JINGNI_DATA_ERROR"


class OrderError(JingniError):
    code = "JINGNI_ORDER_ERROR"

# ---- core/contract.py ----
# -*- coding: utf-8 -*-
"""跨平台统一契约：证券代码、频率、字段。

设计原则：
- 内部规范代码统一为 ``600000.SH`` / ``000001.SZ`` / ``430047.BJ``；
- 平台适配器只在边界做格式转换，策略层不感知平台差异；
- 转换必须幂等，非法输入抛 ``ValidationError``，不静默返回原值。
"""

import re


string_types = (str,)


_MARKET_NAMES = {
    "SH": "SH",
    "SS": "SH",
    "XSHG": "SH",
    "SHSE": "SH",
    "SZ": "SZ",
    "XSHE": "SZ",
    "SZSE": "SZ",
    "BJ": "BJ",
    "BJSE": "BJ",
}

_CODE_RE = re.compile(
    r"^(?:(?P<prefix>SHSE|SZSE|BJSE)\.)?"
    r"(?P<digits>\d{6})"
    r"(?:\.(?P<suffix>SH|SS|SZ|XSHG|XSHE|BJ))?$",
    re.IGNORECASE,
)

_PREFIX_CODE_RE = re.compile(
    r"^(?P<prefix>SH|SZ|BJ)(?P<digits>\d{6})$", re.IGNORECASE
)


_FREQUENCY_ALIASES = {
    "tick": "tick",
    "1m": "1m",
    "1min": "1m",
    "min": "1m",
    "minute": "1m",
    "5m": "5m",
    "5min": "5m",
    "15m": "15m",
    "15min": "15m",
    "30m": "30m",
    "30min": "30m",
    "60m": "60m",
    "60min": "60m",
    "1h": "60m",
    "hour": "60m",
    "1d": "1d",
    "d": "1d",
    "day": "1d",
    "daily": "1d",
    "1w": "1w",
    "w": "1w",
    "week": "1w",
    "weekly": "1w",
}

_VALID_FREQUENCIES = ("tick", "1m", "5m", "15m", "30m", "60m", "1d", "1w", "1M")


_TICK_FIELD_MAP = {
    "goldminer": {
        "open": "open",
        "high": "high",
        "low": "low",
        "close": "price",
        "volume": "volume",
        "amount": "amount",
    },
    "qmt": {
        "open": "open",
        "high": "high",
        "low": "low",
        "close": "lastPrice",
        "volume": "volume",
        "amount": "amount",
    },
    "ptrade": {
        "open": "open_px",
        "high": "high_px",
        "low": "low_px",
        "close": "last_px",
        "volume": "volume",
        "amount": "business_amount",
    },
}


def _market_from_token(token):
    if token is None or token == "":
        return None
    token = str(token).upper()
    if token not in _MARKET_NAMES:
        raise ValidationError("unsupported market token: {0}".format(token))
    return _MARKET_NAMES[token]


def infer_market(digits):
    """根据 6 位代码推断交易所；仅用于无显式市场后缀的输入。"""
    digits = str(digits)
    if len(digits) != 6 or not digits.isdigit():
        raise ValidationError("security code must be 6 digits: {0}".format(digits))
    if digits.startswith("920"):
        return "BJ"
    first = digits[0]
    if first in ("6", "5", "9"):
        return "SH"
    if first in ("0", "1", "2", "3"):
        return "SZ"
    if first in ("4", "8"):
        return "BJ"
    raise ValidationError("cannot infer market from code: {0}".format(digits))


def split_code(code):
    """返回 ``(digits, market)``；market 为 SH/SZ/BJ。"""
    if code is None:
        raise ValidationError("security code is required")
    if isinstance(code, int):
        code = str(code).zfill(6)
    if not isinstance(code, string_types):
        raise ValidationError("security code must be a string or int")
    text = code.strip().upper().replace(" ", "")
    if not text:
        raise ValidationError("security code is empty")

    match = _CODE_RE.match(text)
    if match is None:
        match = _PREFIX_CODE_RE.match(text)
        if match is None:
            raise ValidationError("invalid security code: {0}".format(code))
        prefix_market = _market_from_token(match.group("prefix"))
        digits = match.group("digits")
        return digits, prefix_market

    digits = match.group("digits")
    prefix_market = _market_from_token(match.group("prefix"))
    suffix_market = _market_from_token(match.group("suffix"))
    if prefix_market is not None and suffix_market is not None:
        if prefix_market != suffix_market:
            raise ValidationError(
                "conflicting market in security code: {0}".format(code)
            )
        market = prefix_market
    elif prefix_market is not None:
        market = prefix_market
    elif suffix_market is not None:
        market = suffix_market
    else:
        market = infer_market(digits)
    return digits, market


def normalize_code(code, target=None):
    """把任意受支持的证券代码转换为目标平台格式。

    target: ``None``/``canonical`` 返回 ``600000.SH``；``goldminer``/``gm``
    返回 ``SHSE.600000``；``qmt`` 返回 ``600000.SH``；``ptrade`` 返回
    ``600000.SS``。
    """
    digits, market = split_code(code)
    target_name = "canonical" if target is None else str(target).strip().lower()
    if target_name in ("goldminer", "gm"):
        prefix = {"SH": "SHSE.", "SZ": "SZSE.", "BJ": "BJSE."}[market]
        return prefix + digits
    if target_name == "qmt":
        return digits + "." + market
    if target_name == "ptrade":
        suffix = "SS" if market == "SH" else market
        return digits + "." + suffix
    if target_name in ("canonical", "internal", "jingni"):
        return digits + "." + market
    raise ValidationError("unsupported code target: {0}".format(target))


def normalize_platform(mode):
    """把 gm/goldminer/qmt/ptrade 统一为内部平台名。"""
    if mode is None:
        return None
    text = str(mode).strip().lower()
    if text in ("gm", "goldminer", "掘金"):
        return "goldminer"
    if text in ("qmt", "迅投"):
        return "qmt"
    if text in ("ptrade", "ptrader"):
        return "ptrade"
    return text


def normalize_frequency(frequency):
    """把常见频率别名统一为 tick/1m/5m/15m/30m/60m/1d/1w/1M。"""
    if frequency is None:
        raise ValidationError("frequency is required")
    raw = str(frequency).strip()
    if raw in ("1M", "M", "month", "monthly", "mo"):
        return "1M"
    low = raw.lower()
    if low in _FREQUENCY_ALIASES:
        return _FREQUENCY_ALIASES[low]
    if low in _VALID_FREQUENCIES:
        return low
    raise ValidationError("unsupported frequency: {0}".format(frequency))


def map_history_fields(fields, platform):
    """统一字段名转换为平台字段名列表。"""
    platform = normalize_platform(platform)
    if fields is None or fields == "" or fields == []:
        fields = ["open", "high", "low", "close", "volume", "amount"]
    elif isinstance(fields, string_types):
        fields = [item.strip() for item in fields.split(",") if item.strip()]
    elif not isinstance(fields, (list, tuple)):
        raise ValidationError("fields must be a string or list")

    result = []
    for field in fields:
        name = str(field).strip()
        if platform == "ptrade" and name == "pre_close":
            name = "preclose"
        elif platform == "ptrade" and name == "amount":
            # PTrade get_history/get_price 的成交额字段叫 money。
            name = "money"
        elif platform == "qmt" and name == "pre_close":
            name = "preClose"
        result.append(name)
    if not result:
        raise ValidationError("fields is empty")
    return result


def map_tick_field(field, platform):
    """统一 tick 字段名转换为平台字段名。"""
    platform = normalize_platform(platform)
    if field is None:
        return None
    name = str(field).strip()
    table = _TICK_FIELD_MAP.get(platform, {})
    return table.get(name, name)


def canonical_tick_field(field, platform):
    """平台 tick 字段名转回统一字段名。"""
    platform = normalize_platform(platform)
    if field is None:
        return None
    name = str(field).strip()
    table = _TICK_FIELD_MAP.get(platform, {})
    for canonical, platform_field in table.items():
        if platform_field == name:
            return canonical
    return name


def map_adjust(adjust, platform):
    """统一复权参数转换。"""
    platform = normalize_platform(platform)
    name = "pre" if adjust is None or adjust == "" else str(adjust).lower()
    if name in ("none", "no", "raw", "0", "adjust_none"):
        canonical = "none"
    elif name in ("pre", "prev", "front", "forward", "1", "adjust_prev"):
        canonical = "pre"
    elif name in ("post", "back", "backward", "2", "adjust_post"):
        canonical = "post"
    else:
        raise ValidationError("unsupported adjust: {0}".format(adjust))

    if platform == "goldminer":
        return {"none": "ADJUST_NONE", "pre": "ADJUST_PREV", "post": "ADJUST_POST"}[
            canonical
        ]
    if platform == "qmt":
        return {"none": "none", "pre": "front", "post": "back"}[canonical]
    if platform == "ptrade":
        return {"none": "none", "pre": "pre", "post": "post"}[canonical]
    return canonical

# ---- core/order.py ----
# -*- coding: utf-8 -*-
"""统一订单对象与状态映射。"""

import datetime

ORDER_STATUSES = (
    "PENDING",
    "PARTIAL",
    "FILLED",
    "CANCELED",
    "REJECTED",
    "EXPIRED",
    "UNKNOWN",
)

SIDE_BUY = "BUY"
SIDE_SELL = "SELL"

_GM_STATUS = {
    0: "PENDING",  # Unknown/尚未回报，按待处理展示
    1: "PENDING",  # New
    2: "PARTIAL",  # PartiallyFilled
    3: "FILLED",  # Filled
    5: "CANCELED",  # Canceled
    6: "PENDING",  # PendingCancel
    8: "REJECTED",  # Rejected
    9: "UNKNOWN",  # Suspended
    10: "PENDING",  # PendingNew
    12: "EXPIRED",  # Expired
    15: "PENDING",  # PendingTrigger
    16: "PENDING",  # Triggered
}

_QMT_STATUS = {
    48: "PENDING",
    49: "PENDING",
    50: "PENDING",
    51: "PENDING",
    52: "PARTIAL",
    53: "CANCELED",
    54: "CANCELED",
    55: "PARTIAL",
    56: "FILLED",
    57: "REJECTED",
}

_PTRADE_STATUS = {
    "0": "PENDING",  # 未报
    "1": "PENDING",  # 待报
    "2": "PENDING",  # 已报
    "3": "PENDING",  # 已报待撤
    "4": "PARTIAL",  # 部成待撤
    "5": "CANCELED",  # 部撤
    "6": "CANCELED",  # 已撤
    "7": "PARTIAL",  # 部成
    "8": "FILLED",  # 已成
    "9": "REJECTED",  # 废单
    "+": "PENDING",  # 已受理
    "-": "PENDING",  # 已确认
}

_GM_STATUS_NAMES = {
    "ORDERSTATUS_NEW": "PENDING",
    "ORDERSTATUS_PARTIALLYFILLED": "PARTIAL",
    "ORDERSTATUS_FILLED": "FILLED",
    "ORDERSTATUS_CANCELED": "CANCELED",
    "ORDERSTATUS_REJECTED": "REJECTED",
    "ORDERSTATUS_EXPIRED": "EXPIRED",
}


def normalize_side(value):
    """把平台方向值/文本统一为 BUY/SELL。"""
    if value is None:
        return None
    text = str(value).strip().upper()
    if text in ("BUY", "B", "买", "买入", "23", "1", "ORDER_SIDE_BUY", "ORDERSIDE_BUY"):
        return SIDE_BUY
    if text in ("SELL", "S", "卖", "卖出", "24", "2", "ORDER_SIDE_SELL", "ORDERSIDE_SELL"):
        return SIDE_SELL
    return None


def normalize_status(platform, value):
    """平台状态码转统一枚举；未知返回 UNKNOWN，不猜测。"""
    if value is None:
        return "UNKNOWN"
    if isinstance(value, str):
        text = value.strip().upper()
        if text in ORDER_STATUSES:
            return text
        if platform == "ptrade" and text in _PTRADE_STATUS:
            return _PTRADE_STATUS[text]
        if platform == "goldminer" and text in _GM_STATUS_NAMES:
            return _GM_STATUS_NAMES[text]
        if text.isdigit():
            value = int(text)
        else:
            # 掘金可能返回 OrderStatus_New 这类常量名。
            for candidate in ORDER_STATUSES:
                if text.endswith(candidate):
                    return candidate
            return "UNKNOWN"
    try:
        number = int(value)
    except Exception:
        return "UNKNOWN"
    if platform == "goldminer":
        return _GM_STATUS.get(number, "UNKNOWN")
    if platform == "qmt":
        return _QMT_STATUS.get(number, "UNKNOWN")
    if platform == "ptrade":
        return _PTRADE_STATUS.get(str(number), "UNKNOWN")
    return "UNKNOWN"


def order_ref(platform, platform_id=None, remark=None):
    """构造统一订单引用。"""
    return {
        "platform": platform,
        "id": None if platform_id is None else str(platform_id),
        "remark": None if remark is None else str(remark),
    }


def coerce_order_ref(value):
    """接受 OrderRef/dict/字符串，返回可比较的订单引用。"""
    if value is None:
        return None
    if isinstance(value, dict):
        if "order_ref" in value:
            return value["order_ref"]
        if "platform" in value and "id" in value:
            return value
        if "id" in value:
            return order_ref(value.get("platform"), value["id"], value.get("remark"))
        if "platform_order_id" in value:
            return order_ref(
                value.get("platform"), value["platform_order_id"], value.get("remark")
            )
        return value
    return order_ref(None, value, None)


def make_order(
    platform,
    platform_id=None,
    code=None,
    side=None,
    price=None,
    amount=None,
    filled=0,
    status=None,
    status_code=None,
    created_at=None,
    updated_at=None,
    remark=None,
    raw=None,
):
    """构造统一订单字典。"""
    return {
        "order_ref": order_ref(platform, platform_id, remark),
        "platform_order_id": None if platform_id is None else str(platform_id),
        "code": code,
        "side": normalize_side(side),
        "price": _to_float(price),
        "amount": _to_int(amount),
        "filled": _to_int(filled),
        "status": normalize_status(platform, status),
        "status_code": status_code if status_code is not None else status,
        "created_at": created_at,
        "updated_at": updated_at,
        "remark": remark,
        "raw": raw,
    }


def _to_float(value):
    if value is None:
        return None
    try:
        return float(value)
    except Exception:
        return None


def _to_int(value):
    if value is None:
        return None
    try:
        return int(float(value))
    except Exception:
        return None


def ref_matches(order, ref):
    """判断订单是否匹配某个 OrderRef/字符串。"""
    if ref is None:
        return True
    target = coerce_order_ref(ref)
    if isinstance(target, str):
        target = order_ref(None, target, None)
    if not isinstance(target, dict):
        return False
    order_id = str(order.get("platform_order_id") or "")
    order_remark = str(order.get("remark") or "")
    target_id = str(target.get("id") or "")
    target_remark = str(target.get("remark") or "")
    if target_id and target_id == order_id:
        return True
    if target_remark and target_remark == order_remark:
        return True
    return False


def now_text(value=None):
    value = value or datetime.datetime.now()
    return value.strftime("%Y-%m-%d %H:%M:%S")

# ---- core/risk.py ----
# -*- coding: utf-8 -*-
"""无平台依赖的订单风控。"""



def _state(context):
    state = getattr(context, "_jingni_risk_state", None)
    if state is None:
        state = {"last": {}, "date": None, "count": 0, "kill_switch": False}
        context._jingni_risk_state = state
    return state


def _to_float(value):
    try:
        return float(value)
    except Exception:
        return None


def _available_from_positions(positions, code):
    available = 0
    for item in positions or []:
        if str(item.get("code") or "") != str(code):
            continue
        available = int(item.get("available") or 0)
        break
    return max(0, available)


def check_order(
    context,
    code,
    side,
    amount,
    price=None,
    account=None,
    positions=None,
    now=None,
    record=True,
    check_sell_available=True,
):
    """下单前统一风控；返回 ``(ok, reason)``。

    ``amount`` 为正数。买方向按股票 100 股整手校验；卖方向按统一
    ``available`` 校验。账户/持仓由调用方传入，避免本模块反向依赖适配器。
    ``record=False`` 用于 dry-run：只检查，不消耗每日笔数/重复窗口。
    """
    config = context.config
    state = _state(context)
    if config.kill_switch or state.get("kill_switch"):
        return False, "kill_switch is active"
    side = normalize_side(side)
    if side not in (SIDE_BUY, SIDE_SELL):
        return False, "invalid side"
    try:
        amount = int(amount)
    except Exception:
        return False, "amount must be an integer"
    if amount <= 0:
        return False, "amount must be positive"
    price_value = _to_float(price)
    if price is not None and (price_value is None or price_value <= 0):
        return False, "price must be positive"
    if side == SIDE_BUY and amount % 100 != 0:
        return False, "A-share buy amount must be a multiple of 100"
    if config.max_order_amount is not None and amount > int(config.max_order_amount):
        return False, "amount exceeds max_order_amount"
    if (
        side == SIDE_BUY
        and price_value is not None
        and config.max_order_value is not None
        and amount * price_value > float(config.max_order_value)
    ):
        return False, "value exceeds max_order_value"

    day = context.trade_date()
    if state.get("date") != day:
        state["date"] = day
        state["count"] = 0
        state["last"] = {}
    if config.max_daily_orders is not None and state["count"] >= int(
        config.max_daily_orders
    ):
        return False, "daily order limit reached"
    if config.repeat_window_seconds:
        key = (str(code), side, amount, price_value)
        now_value = now or context.now()
        last = state["last"].get(key)
        if last is not None:
            elapsed = (now_value - last).total_seconds()
            if elapsed < float(config.repeat_window_seconds):
                return False, "duplicate order within repeat window"

    if side == SIDE_SELL and check_sell_available:
        available = _available_from_positions(positions, code)
        if amount > available:
            return False, "amount exceeds available position"
    elif account is not None and price_value is not None:
        cash = _to_float(account.get("available", account.get("cash")))
        if cash is not None and amount * price_value > cash:
            return False, "insufficient cash"

    if record:
        state["count"] += 1
        if config.repeat_window_seconds and price_value is not None:
            state["last"][(str(code), side, amount, price_value)] = now or context.now()
    return True, "ok"


def calc_max_buy(account, price, lot_size=100):
    """按可用资金计算最大可买数量（整手向下取整）。"""
    cash = _to_float(account.get("available", account.get("cash"))) if account else 0
    price_value = _to_float(price)
    if not cash or not price_value or price_value <= 0:
        return 0
    return int((cash / price_value) / lot_size) * lot_size


def calc_max_sell(positions, code):
    """按统一持仓计算最大可卖数量。"""
    return _available_from_positions(positions, code)


def set_kill_switch(context, enabled=True):
    state = _state(context)
    state["kill_switch"] = bool(enabled)
    context.config.kill_switch = bool(enabled)
    return state["kill_switch"]

