# -*- coding: utf-8 -*-
"""运行配置。"""


class RuntimeConfig(object):
    """一次策略运行的配置；默认值按 D7 的安全口径。"""

    def __init__(
        self,
        account_id=None,
        account_type="stock",
        dry_run=True,
        max_order_amount=100000,
        max_order_value=1000000.0,
        max_daily_orders=100,
        repeat_window_seconds=3,
        log_level="INFO",
        legacy=False,
        kill_switch=False,
    ):
        self.account_id = account_id
        self.account_type = account_type
        self.dry_run = bool(dry_run)
        self.max_order_amount = max_order_amount
        self.max_order_value = max_order_value
        self.max_daily_orders = max_daily_orders
        self.repeat_window_seconds = repeat_window_seconds
        self.log_level = log_level
        self.legacy = bool(legacy)
        self.kill_switch = bool(kill_switch)

    def update(self, **kwargs):
        for key, value in kwargs.items():
            if hasattr(self, key):
                setattr(self, key, value)
        return self

    def as_dict(self):
        return {
            "account_id": self.account_id,
            "account_type": self.account_type,
            "dry_run": self.dry_run,
            "max_order_amount": self.max_order_amount,
            "max_order_value": self.max_order_value,
            "max_daily_orders": self.max_daily_orders,
            "repeat_window_seconds": self.repeat_window_seconds,
            "log_level": self.log_level,
            "legacy": self.legacy,
            "kill_switch": self.kill_switch,
        }

# ---- core/runtime.py ----
# -*- coding: utf-8 -*-
"""运行上下文与平台 API 解析。

三家平台的 API 都不是可以稳定 import 的普通包：
- 掘金通过 ``gm.api`` 注入；
- QMT 在策略模块的全局命名空间中注入；
- PTrade 在策略模块的全局命名空间中注入。

因此这里用一个很小的 ``platform_call`` 解析器：优先当前模块全局，
其次 ``__main__`` 全局，再次显式注册表（测试/嵌入场景），最后尝试
``gm.api``。单文件发行物被复制到策略尾部时，前两种方式即可工作。
"""

import datetime



DEFAULT_MODE = "软件名称"
_PLATFORM_APIS = {}
_CONTEXT_CACHE = {}


def python_version_text():
    """返回 Python 版本文本；PTrade 禁用系统模块，失败时降级为 unknown。"""
    try:
        return __import__("platform").python_version()
    except Exception:
        return "unknown"


def _main_namespace():
    """返回策略主模块命名空间；单文件模式下就是当前 globals。"""
    if "__name__" in globals() and globals().get("__name__") == "__main__":
        return globals()
    try:
        main = __import__("__main__")
    except Exception:
        return globals()
    return getattr(main, "__dict__", None) or globals()


def set_default_mode(mode):
    global DEFAULT_MODE
    DEFAULT_MODE = normalize_platform(mode) or mode
    return DEFAULT_MODE


def get_default_mode():
    """读取策略模块的 trade_mode；兼容旧全局变量。"""
    current = globals().get("trade_mode")
    if current and current != "软件名称":
        return normalize_platform(current)
    main = _main_namespace()
    value = main.get("trade_mode")
    if value and value != "软件名称":
        return normalize_platform(value)
    return normalize_platform(DEFAULT_MODE) or DEFAULT_MODE


def register_api(mapping):
    """注册平台函数表，主要用于测试或嵌入式运行。"""
    if mapping:
        _PLATFORM_APIS.update(mapping)
    return _PLATFORM_APIS


def clear_api_registry():
    _PLATFORM_APIS.clear()
    _CONTEXT_CACHE.clear()


def get_platform_global(name, default=None):
    """从当前模块或 __main__ 读取平台注入的全局变量。"""
    if name in globals():
        return globals()[name]
    main = _main_namespace()
    if name in main:
        return main[name]
    return default


def get_platform_constant(name, default=None):
    """读取平台常量（如 OrderSide_Buy / ADJUST_PREV）。"""
    value = get_platform_global(name)
    if value is not None:
        return value
    if name in _PLATFORM_APIS:
        return _PLATFORM_APIS[name]
    try:
        import gm.api as gm_api

        return getattr(gm_api, name, default)
    except Exception:
        return default


def platform_call(name, *args, **kwargs):
    """按优先级解析并调用平台函数。"""
    fn = globals().get(name)
    if fn is None:
        main = _main_namespace()
        fn = main.get(name)
    if fn is None:
        fn = _PLATFORM_APIS.get(name)
    if fn is None:
        try:
            import gm.api as gm_api

            fn = getattr(gm_api, name, None)
        except Exception:
            fn = None
    if fn is None:
        raise PlatformApiMissing("platform api not found: {0}".format(name))
    return fn(*args, **kwargs)


def _detect_mode(platform, raw):
    if raw is None:
        return "unknown"
    if platform == "goldminer":
        mode = getattr(raw, "mode", None)
        if mode == 1:
            return "live"
        if mode == 2:
            return "backtest"
        return "unknown"
    if platform == "qmt":
        return "backtest" if bool(getattr(raw, "do_back_test", False)) else "live"
    if platform == "ptrade":
        try:
            return "live" if bool(platform_call("is_trade")) else "backtest"
        except Exception:
            return "unknown"
    return "unknown"


class RuntimeContext(object):
    """平台无关的运行上下文。"""

    def __init__(self, platform, raw=None, config=None):
        self.platform = normalize_platform(platform) or platform
        self.raw = raw
        self.config = config or RuntimeConfig()
        self.mode = _detect_mode(self.platform, raw)

    @property
    def is_backtest(self):
        return self.mode == "backtest"

    @property
    def is_live(self):
        return self.mode == "live"

    def now(self):
        """返回策略时钟；QMT/PTrade 优先使用回测时钟。"""
        try:
            if self.platform == "goldminer" and self.raw is not None:
                value = getattr(self.raw, "now", None)
                if callable(value):
                    value = value()
                if value is not None:
                    return value
            if self.platform == "qmt" and self.raw is not None:
                barpos = getattr(self.raw, "barpos", None)
                if barpos is not None:
                    timetag = self.raw.get_bar_timetag(barpos)
                    value = platform_call(
                        "timetag_to_datetime", timetag, "%Y-%m-%d %H:%M:%S"
                    )
                    if isinstance(value, str):
                        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y%m%d%H%M%S"):
                            try:
                                return datetime.datetime.strptime(value, fmt)
                            except ValueError:
                                continue
                    return value
            if self.platform == "ptrade" and self.raw is not None:
                blotter = getattr(self.raw, "blotter", None)
                current_dt = getattr(blotter, "current_dt", None)
                if current_dt is not None:
                    return current_dt
        except Exception:
            pass
        return datetime.datetime.now()

    def trade_date(self, fmt="%Y%m%d"):
        return self.now().strftime(fmt)

    def account_id(self):
        if self.config.account_id:
            return self.config.account_id
        return get_platform_global("account")


def resolve_context(trade_mode, context_data, config=None):
    """把旧式 (trade_mode, context_data) 解析为 RuntimeContext。"""
    if isinstance(trade_mode, RuntimeContext):
        if config is not None:
            trade_mode.config = config
        return trade_mode
    platform = normalize_platform(trade_mode) or get_default_mode()
    raw = context_data
    key = (platform, id(raw) if raw is not None else None)
    context = _CONTEXT_CACHE.get(key)
    if context is None:
        context = RuntimeContext(platform, raw=raw, config=config)
        _CONTEXT_CACHE[key] = context
    elif config is not None:
        context.config = config
    return context

# ---- core/calendar.py ----
# -*- coding: utf-8 -*-
"""交易日历与会话时间的无平台依赖工具。"""

import datetime


def normalize_date(value):
    """把日期/时间/字符串统一为 ``YYYYMMDD``；无法识别返回 None。"""
    if value is None:
        return None
    if isinstance(value, datetime.datetime):
        return value.strftime("%Y%m%d")
    if isinstance(value, datetime.date):
        return value.strftime("%Y%m%d")
    text = str(value).strip().replace("-", "").replace("/", "")
    if len(text) < 8 or not text[:8].isdigit():
        return None
    return text[:8]


def format_date(value, sep="-"):
    """统一为 ``YYYY-MM-DD``（sep='' 时为 YYYYMMDD）。"""
    text = normalize_date(value)
    if text is None:
        return None
    if sep == "":
        return text
    return "{0}{1}{2}{1}{3}".format(
        text[:4], sep, text[4:6], text[6:8]
    )


def is_trading_session(value, include_auction=False):
    """判断时间是否落在 A 股连续竞价/集合竞价时段。

    默认只判断连续竞价：09:30—11:30、13:00—15:00。
    ``include_auction=True`` 时额外包含 09:15—09:25 开盘集合竞价。
    不判断节假日；节假日由交易日历接口负责。
    """
    if isinstance(value, datetime.datetime):
        current = value.time()
    elif isinstance(value, datetime.time):
        current = value
    else:
        return False
    if include_auction:
        if datetime.time(9, 15) <= current <= datetime.time(9, 25):
            return True
    if datetime.time(9, 30) <= current <= datetime.time(11, 30):
        return True
    if datetime.time(13, 0) <= current <= datetime.time(15, 0):
        return True
    return False


def is_weekday(value):
    if isinstance(value, datetime.datetime):
        return value.weekday() < 5
    if isinstance(value, datetime.date):
        return value.weekday() < 5
    text = normalize_date(value)
    if text is None:
        return False
    try:
        return datetime.datetime.strptime(text, "%Y%m%d").weekday() < 5
    except ValueError:
        return False

# ---- core/instrument.py ----
# -*- coding: utf-8 -*-
"""标的元数据的无平台依赖归一化工具。"""

import datetime



def board_from_code(code):
    """根据规范代码推断板块名称。"""
    try:
        digits, market = split_code(code)
    except Exception:
        return None
    if market == "BJ" or digits.startswith(("4", "8", "920")):
        return "北交所"
    if digits.startswith(("688", "689")):
        return "科创板"
    if digits.startswith(("300", "301")):
        return "创业板"
    return "主板"


def date_iso(value):
    """平台日期字段统一为 ``YYYY-MM-DD``；QMT 特殊值原样保留为 None。"""
    if value is None:
        return None
    if isinstance(value, datetime.datetime):
        return value.strftime("%Y-%m-%d")
    if isinstance(value, datetime.date):
        return value.strftime("%Y-%m-%d")
    text = str(value).strip()
    if not text or text in ("0", "19700101"):
        return None
    # QMT 使用 19700101—19700106 表示新股/新债等特殊状态。
    if text.startswith("1970010"):
        return None
    compact = text.replace("-", "").replace("/", "")
    if len(compact) >= 8 and compact[:8].isdigit():
        return format_date(compact[:8])
    return text or None


def to_float(value):
    if value is None or value == "":
        return None
    try:
        return float(value)
    except Exception:
        return None


def to_int(value):
    if value is None or value == "":
        return None
    try:
        return int(float(value))
    except Exception:
        return None


def bool_or_none(value):
    """平台布尔/数值状态转 bool；未知保持 None。"""
    if value is None or value == "":
        return None
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in ("1", "true", "yes", "y", "t"):
        return True
    if text in ("0", "false", "no", "n", "f"):
        return False
    return None


def first_value(data, keys, default=None):
    """从 dict/对象中按候选字段名取第一个非空值。"""
    if data is None:
        return default
    for key in keys:
        if isinstance(data, dict):
            value = data.get(key)
        else:
            value = getattr(data, key, None)
        if value is not None and value != "":
            return value
    return default


def records(payload):
    """把 DataFrame / list / dict 统一成记录列表。"""
    if payload is None:
        return []
    if hasattr(payload, "to_dict"):
        try:
            return payload.to_dict("records")
        except Exception:
            pass
    if isinstance(payload, dict):
        if isinstance(payload.get("data"), (list, tuple)):
            return list(payload["data"])
        # 平台可能返回 {code: detail}；只把 detail 值当记录。
        if payload and any(isinstance(v, dict) for v in payload.values()):
            rows = []
            for key, value in payload.items():
                if not isinstance(value, dict):
                    continue
                row = dict(value)
                row.setdefault("symbol", key)
                row.setdefault("sec_id", key)
                rows.append(row)
            if rows:
                return rows
        return [payload]
    if isinstance(payload, (list, tuple)):
        return list(payload)
    return [payload]


def build_instrument(
    code,
    name=None,
    board=None,
    lot_size=None,
    tick_size=None,
    limit_up=None,
    limit_down=None,
    listed_date=None,
    status=None,
):
    """构造统一标的元数据；status 为 st/suspend/delisted 的 dict。"""
    canonical = normalize_code(code)
    current = {
        "st": None,
        "suspend": None,
        "delisted": None,
    }
    if isinstance(status, dict):
        current.update(status)
    return {
        "code": canonical,
        "name": name,
        "board": board or board_from_code(canonical),
        "lot_size": to_int(lot_size) or 100,
        "tick_size": to_float(tick_size),
        "limit_up": to_float(limit_up),
        "limit_down": to_float(limit_down),
        "listed_date": date_iso(listed_date),
        "status": current,
    }

# ---- adapters/base.py ----
# -*- coding: utf-8 -*-
"""适配器基类：只负责原生调用、字段映射和异常翻译。"""

import pandas as pd



class BaseAdapter(object):
    platform = "base"

    def __init__(self, context):
        self.context = context
        self.platform = normalize_platform(context.platform) or context.platform

    def normalize_code(self, code):
        return normalize_code(code, self.platform)

    def normalize_frequency(self, frequency):
        return normalize_frequency(frequency)

    def get_history(
        self, code, frequency="1d", count=1, end_time=None, fields=None, adjust=None
    ):
        raise NotImplementedError

    def get_history_native(
        self, code, frequency="1d", count=1, end_time=None, fields=None, adjust=None
    ):
        """旧接口返回形态；默认与统一形态一致。"""
        return self.get_history(code, frequency, count, end_time, fields, adjust)

    def get_history_range(
        self, code, frequency="1d", start_time=None, end_time=None, fields=None, adjust=None
    ):
        """按时间范围取历史行情；子类必须显式实现。"""
        raise NotImplementedError

    def download_history(
        self, codes, frequency="1d", start_time=None, end_time=None
    ):
        """下载/预热本地历史数据；默认平台（GM/PTrade）无需下载。"""
        return None

    def get_instruments(self, codes):
        """批量取标的元数据，返回 ``{canonical_code: dict}``。"""
        raise NotImplementedError

    def get_stock_status(self, codes, query_type="ST", date=None):
        """批量取股票状态，返回 ``{canonical_code: bool/None}``。"""
        raise NotImplementedError

    def get_trading_dates(self, start_date=None, end_date=None, market="SH"):
        """取交易日列表，返回 ``YYYYMMDD`` 字符串列表。"""
        raise NotImplementedError

    def get_tick_raw(self, codes, fields=None):
        raise NotImplementedError

    def get_tick(self, codes, fields=None):
        """返回 ``{canonical_code: {canonical_field: value}}``。"""
        raw = self.get_tick_raw(codes, fields)
        if not raw:
            return {}
        if isinstance(raw, dict):
            items = list(raw.items())
        elif isinstance(raw, (list, tuple)):
            items = []
            for index, item in enumerate(raw):
                if not isinstance(item, dict):
                    continue
                key = item.get("symbol") or item.get("code") or (
                    codes[index] if isinstance(codes, (list, tuple)) else codes
                )
                items.append((key, item))
        else:
            raise DataError("unsupported tick payload: {0}".format(type(raw)))

        result = {}
        for key, item in items:
            if not isinstance(item, dict):
                continue
            try:
                canonical = normalize_code(key)
            except Exception:
                canonical = str(key)
            values = {}
            for raw_field, value in item.items():
                canonical_field = canonical_tick_field(raw_field, self.platform)
                values[canonical_field] = value
            if fields:
                wanted = []
                for field in fields:
                    wanted.append(str(field))
                values = dict((k, v) for k, v in values.items() if k in wanted)
            result[canonical] = values
        return result

    def get_portfolio(self, field):
        raise NotImplementedError

    def order(self, code, side, amount, price=None, order_type="limit", remark=None):
        raise NotImplementedError

    def cancel(self, order_ref):
        raise NotImplementedError

    def cancel_all(self):
        raise NotImplementedError

    def get_orders(self, status=None, include_finished=True):
        raise NotImplementedError

    def get_trades(self, order_ref=None):
        raise NotImplementedError

    def get_positions(self):
        return self.get_portfolio("positions")

    def get_account(self):
        return {
            "total_asset": self.get_portfolio("assets_value"),
            "cash": self.get_portfolio("cash"),
            "available": self.get_portfolio("cash"),
            "market_value": self.get_portfolio("market_value"),
            "frozen": None,
            "pnl": None,
            "raw": None,
        }

    def _make_order(self, raw, code=None, side=None, amount=None, price=None, remark=None):
        """由平台原始订单构造统一订单；子类可覆盖字段映射。"""
        if isinstance(raw, dict):
            platform_id = (
                raw.get("cl_ord_id")
                or raw.get("order_id")
                or raw.get("id")
                or raw.get("m_strOrderSysID")
            )
            created = raw.get("created_at") or raw.get("insert_time")
            filled = raw.get("filled_volume") or raw.get("filled") or 0
            status = raw.get("status")
        else:
            platform_id = getattr(raw, "cl_ord_id", None)
            created = getattr(raw, "created_at", None)
            filled = getattr(raw, "filled_volume", 0)
            status = getattr(raw, "status", None)
        return make_order(
            self.platform,
            platform_id=platform_id or remark,
            code=code,
            side=side,
            price=price,
            amount=amount,
            filled=filled,
            status=status,
            created_at=created,
            remark=remark,
            raw=raw,
        )

    def frame(self, data, code=None):
        """把平台返回统一成 DataFrame，并处理 QMT 的字典/多级列。"""
        if data is None:
            return pd.DataFrame()
        current = data
        if isinstance(current, dict):
            candidates = []
            if code is not None:
                candidates.append(code)
                try:
                    candidates.append(normalize_code(code, self.platform))
                    candidates.append(normalize_code(code))
                except Exception:
                    pass
            for key in candidates:
                if key in current:
                    current = current[key]
                    break
            else:
                if len(current) == 1:
                    current = list(current.values())[0]
                else:
                    raise DataError(
                        "history payload has multiple codes but none matched: {0}".format(
                            code
                        )
                    )
        if not isinstance(current, pd.DataFrame):
            try:
                current = pd.DataFrame(current)
            except Exception as exc:
                raise DataError("cannot convert history payload to DataFrame: {0}".format(exc))
        if isinstance(current.columns, pd.MultiIndex):
            try:
                if code is not None:
                    for level in range(current.columns.nlevels):
                        values = current.columns.get_level_values(level)
                        if code in values:
                            current = current.xs(code, axis=1, level=level)
                            break
                        try:
                            normalized = normalize_code(code, self.platform)
                        except Exception:
                            normalized = None
                        if normalized is not None and normalized in values:
                            current = current.xs(normalized, axis=1, level=level)
                            break
                if isinstance(current.columns, pd.MultiIndex):
                    current.columns = [
                        "_".join([str(part) for part in col if part not in ("", None)])
                        for col in current.columns
                    ]
            except Exception:
                pass
        try:
            if current.index.name in ("stime", "time", "date", "datetime"):
                current = current.sort_index()
        except Exception:
            pass
        return current

    def column(self, frame, field):
        """从 DataFrame 取字段列，兼容单列/多级列/字段别名。"""
        if frame is None or frame.empty:
            return pd.Series([], dtype=float)
        if field in frame.columns:
            return frame[field]
        lowered = dict((str(col).lower(), col) for col in frame.columns)
        if str(field).lower() in lowered:
            return frame[lowered[str(field).lower()]]
        if len(frame.columns) == 1:
            return frame[frame.columns[0]]
        raise DataError("field not found in history data: {0}".format(field))

# ---- adapters/goldminer.py ----
# -*- coding: utf-8 -*-
"""掘金量化适配器。"""

import datetime



class GoldminerAdapter(BaseAdapter):
    platform = "goldminer"

    def get_history(
        self, code, frequency="1d", count=1, end_time=None, fields=None, adjust=None
    ):
        code = self.normalize_code(code)
        freq = normalize_frequency(frequency)
        fields = map_history_fields(fields, self.platform)
        end = end_time or self.context.now()
        if isinstance(end, datetime.datetime):
            fmt = "%Y-%m-%d" if freq in ("1d", "1w", "1M") else "%Y-%m-%d %H:%M:%S"
            end_text = end.strftime(fmt)
        else:
            end_text = str(end)
        data = platform_call(
            "history_n",
            symbol=code,
            frequency=freq,
            count=int(count),
            end_time=end_text,
            fields=",".join(fields),
            adjust=get_platform_constant(map_adjust(adjust, self.platform)),
            df=True,
        )
        return self.frame(data, code)

    def get_history_native(
        self, code, frequency="1d", count=1, end_time=None, fields=None, adjust=None
    ):
        return self.get_history(code, frequency, count, end_time, fields, adjust)

    def get_history_range(
        self, code, frequency="1d", start_time=None, end_time=None, fields=None, adjust=None
    ):
        code = self.normalize_code(code)
        freq = normalize_frequency(frequency)
        fields = map_history_fields(fields, self.platform)
        start = _range_time_text(start_time)
        end = _range_time_text(end_time or self.context.now())
        data = platform_call(
            "history",
            symbol=code,
            frequency=freq,
            start_time=start,
            end_time=end,
            fields=",".join(fields),
            adjust=get_platform_constant(map_adjust(adjust, self.platform)),
            df=True,
        )
        return self.frame(data, code)

    def get_instruments(self, codes):
        if not isinstance(codes, (list, tuple)):
            codes = [codes]
        symbols = [self.normalize_code(code) for code in codes]
        data = None
        try:
            data = platform_call("get_instruments", symbols=symbols, df=True)
        except Exception:
            data = None
        if data is None:
            try:
                data = platform_call(
                    "get_symbol_infos",
                    sec_type1=1010,
                    symbols=symbols,
                    df=True,
                )
            except Exception:
                data = None
        result = {}
        for row in records(data):
            raw_code = first_value(row, ("symbol", "sec_id", "sec_code", "code"))
            if raw_code is None:
                continue
            try:
                canonical = normalize_code(raw_code)
            except Exception:
                continue
            listed = first_value(row, ("listed_date", "open_date", "list_date"))
            delisted = first_value(row, ("delisted_date", "de_listed_date"))
            result[canonical] = build_instrument(
                canonical,
                name=first_value(row, ("sec_name", "symbol_name", "instrument_name", "name")),
                board=first_value(row, ("board", "sector")) or board_from_code(canonical),
                lot_size=first_value(row, ("lot_size", "volume_multiple", "round_lot"), 100),
                tick_size=first_value(row, ("price_tick", "tick_size")),
                limit_up=first_value(row, ("limit_up", "upper_limit", "up_limit")),
                limit_down=first_value(row, ("limit_down", "lower_limit", "down_limit")),
                listed_date=listed,
                status={
                    "st": _state_bool(first_value(row, ("is_st", "st", "st_status"))),
                    "suspend": _state_bool(
                        first_value(row, ("is_suspended", "suspended", "is_suspend"))
                    ),
                    "delisted": _is_delisted(delisted),
                },
            )
        for code in codes:
            canonical = normalize_code(code)
            if canonical not in result:
                result[canonical] = build_instrument(canonical)
        return result

    def get_stock_status(self, codes, query_type="ST", date=None):
        if not isinstance(codes, (list, tuple)):
            codes = [codes]
        instruments = self.get_instruments(codes)
        key = {
            "ST": "st",
            "HALT": "suspend",
            "SUSPEND": "suspend",
            "DELISTING": "delisted",
            "DELISTED": "delisted",
        }.get(str(query_type).upper(), "st")
        return dict(
            (code, (instruments.get(code) or {}).get("status", {}).get(key))
            for code in [normalize_code(item) for item in codes]
        )

    def get_trading_dates(self, start_date=None, end_date=None, market="SH"):
        current = self.context.trade_date()
        start = normalize_date(start_date) or current
        end = normalize_date(end_date) or start
        exchange = _exchange(market)
        rows = None
        api_available = False
        try:
            rows = platform_call(
                "get_trading_dates_by_year",
                exchange=exchange,
                start_year=int(start[:4]),
                end_year=int(end[:4]),
            )
            api_available = True
        except Exception:
            rows = None
        values = []
        for row in records(rows):
            if isinstance(row, (datetime.date, datetime.datetime)):
                values.append(normalize_date(row))
                continue
            if isinstance(row, str):
                values.append(normalize_date(row))
                continue
            value = first_value(row, ("trade_date", "date", "trade_day"))
            if value is not None:
                values.append(normalize_date(value))
        if not values:
            try:
                native = platform_call(
                    "get_trading_dates",
                    exchange=exchange,
                    start_date=start,
                    end_date=end,
                )
                api_available = True
                for item in native or []:
                    values.append(normalize_date(item))
            except Exception:
                pass
        if not api_available:
            raise PlatformApiMissing("goldminer trading calendar is unavailable")
        return sorted(set(item for item in values if item and start <= item <= end))

    def get_tick_raw(self, codes, fields=None):
        if not isinstance(codes, (list, tuple)):
            codes = [codes]
        symbols = [self.normalize_code(code) for code in codes]
        platform_fields = None
        if fields:
            platform_fields = [
                map_tick_field(field, self.platform) for field in fields
            ]
        kwargs = {"symbols": ",".join(symbols)}
        if platform_fields:
            kwargs["fields"] = ",".join(platform_fields)
        return platform_call("current", **kwargs)

    def get_portfolio(self, field):
        try:
            account = self.context.raw.account()
        except Exception as exc:
            raise PlatformApiMissing("goldminer account() failed: {0}".format(exc))
        cash = account.cash
        positions = account.positions()
        if field == "assets_value":
            return cash["nav"]
        if field == "market_value":
            return cash["market_value"]
        if field == "cash":
            return cash["balance"]
        if field == "positions":
            return positions
        raise PlatformApiMissing("unsupported portfolio field: {0}".format(field))

    def _normalize_order(self, raw, code=None, side=None, amount=None, price=None, remark=None):
        if isinstance(raw, dict):
            data = raw
        else:
            data = {}
            for key in (
                "cl_ord_id",
                "order_id",
                "ord_id",
                "symbol",
                "side",
                "price",
                "volume",
                "filled_volume",
                "status",
                "created_at",
                "insert_time",
                "order_remark",
            ):
                value = getattr(raw, key, None)
                if value is not None:
                    data[key] = value
        raw_code = data.get("symbol") or code
        try:
            raw_code = normalize_code(raw_code)
        except Exception:
            pass
        return make_order(
            self.platform,
            platform_id=data.get("cl_ord_id")
            or data.get("order_id")
            or data.get("ord_id")
            or remark,
            code=raw_code,
            side=data.get("side") or side,
            price=data.get("price", price),
            amount=data.get("volume", amount),
            filled=data.get("filled_volume", 0),
            status=data.get("status"),
            status_code=data.get("status"),
            created_at=data.get("created_at") or data.get("insert_time"),
            remark=remark or data.get("order_remark"),
            raw=raw,
        )

    def order(self, code, side, amount, price=None, order_type="limit", remark=None):
        code = self.normalize_code(code)
        side = str(side).upper()
        side_value = get_platform_constant(
            "OrderSide_Buy" if side == SIDE_BUY else "OrderSide_Sell"
        )
        order_type_value = get_platform_constant(
            "OrderType_Market" if order_type == "market" else "OrderType_Limit"
        )
        effect = get_platform_constant(
            "PositionEffect_Open" if side == SIDE_BUY else "PositionEffect_Close"
        )
        duration = get_platform_constant("OrderDuration_GFD", 3)
        raw = platform_call(
            "order_volume",
            symbol=code,
            volume=int(amount),
            price=float(price or 0),
            side=side_value,
            order_type=order_type_value,
            position_effect=effect,
            order_duration=duration,
        )
        # 掘金 order_volume 返回 list[Order]；取第一笔，避免把 list 丢掉后
        # 只能拿 remark 当 platform_order_id。
        if isinstance(raw, (list, tuple)):
            raw = raw[0] if raw else None
        return self._normalize_order(
            raw, code=normalize_code(code), side=side, amount=amount, price=price, remark=remark
        )

    def cancel(self, order_ref):
        ref = coerce_order_ref(order_ref)
        if not isinstance(ref, dict):
            return False
        raw_order = order_ref.get("raw") if isinstance(order_ref, dict) else None
        # 优先使用原始 Order 的 cl_ord_id；ref["id"] 在下单返回对象不完整时
        # 可能只是 remark，直接拿去撤单会被柜台当成未知委托。
        order_id = None
        if raw_order is not None:
            if isinstance(raw_order, dict):
                order_id = raw_order.get("cl_ord_id")
            else:
                order_id = getattr(raw_order, "cl_ord_id", None)
        order_id = order_id or ref.get("platform_order_id") or ref.get("id") or ref.get("remark")
        if not order_id:
            return False
        # 掘金 order_cancel 的每个字典必须同时包含 cl_ord_id 和 account_id。
        # 注意：Order.account_id 在部分仿真环境会被填成 strategy_id，不能
        # 直接当账户号；优先从 Account/Cash 对象取真实 account_id。
        account_id = None
        try:
            account = self.context.raw.account()
            cash = getattr(account, "cash", None)
            if isinstance(cash, dict):
                account_id = cash.get("account_id")
            if not account_id:
                account_id = getattr(cash, "account_id", None)
            if not account_id:
                account_id = getattr(account, "id", None)
            if not account_id:
                account_id = getattr(account, "account_id", None)
        except Exception:
            account_id = None
        if not account_id:
            account_id = getattr(self.context.config, "account_id", None)
        if not account_id and raw_order is not None:
            if isinstance(raw_order, dict):
                account_id = raw_order.get("account_name") or raw_order.get("account_id")
            else:
                account_id = getattr(raw_order, "account_name", None) or getattr(
                    raw_order, "account_id", None
                )
        if not account_id:
            return False
        payload = {"cl_ord_id": str(order_id), "account_id": str(account_id)}
        # 掘金 Python SDK 的 order_cancel 接收单个字典，也接受字典列表。
        result = platform_call("order_cancel", wait_cancel_orders=[payload])
        return bool(result) if result is not None else True

    def cancel_all(self):
        result = platform_call("order_cancel_all")
        return result

    def get_orders(self, status=None, include_finished=True):
        try:
            rows = platform_call("get_orders")
        except Exception:
            rows = None
        if rows is None and not include_finished:
            try:
                rows = platform_call("get_unfinished_orders")
            except Exception:
                rows = []
        result = []
        for row in rows or []:
            order = self._normalize_order(row)
            if status is not None and order["status"] != str(status).upper():
                continue
            if not include_finished and order["status"] in ("FILLED", "CANCELED", "REJECTED", "EXPIRED"):
                continue
            result.append(order)
        return result

    def get_trades(self, order_ref=None):
        try:
            rows = platform_call("get_execution_reports")
        except Exception:
            rows = []
        result = []
        for row in rows or []:
            if isinstance(row, dict):
                data = row
            else:
                data = {}
                for key in (
                    "cl_ord_id",
                    "order_id",
                    "symbol",
                    "price",
                    "volume",
                    "side",
                    "created_at",
                ):
                    value = getattr(row, key, None)
                    if value is not None:
                        data[key] = value
            ref = coerce_order_ref(order_ref)
            if ref is not None:
                ids = (
                    str(data.get("cl_ord_id") or ""),
                    str(data.get("order_id") or ""),
                )
                if isinstance(ref, dict) and ref.get("id") and str(ref["id"]) not in ids:
                    continue
            result.append(
                {
                    "code": self._safe_code(data.get("symbol")),
                    "order_id": data.get("cl_ord_id") or data.get("order_id"),
                    "price": data.get("price"),
                    "amount": data.get("volume"),
                    "side": normalize_side(data.get("side")),
                    "created_at": data.get("created_at"),
                    "raw": row,
                }
            )
        return result

    def get_positions(self):
        positions = []
        for item in self.get_portfolio("positions") or []:
            data = item if isinstance(item, dict) else getattr(item, "__dict__", {})
            code = self._safe_code(
                data.get("symbol") or getattr(item, "symbol", None)
            )
            total = int(data.get("volume") or getattr(item, "volume", 0) or 0)
            today = int(
                data.get("volume_today") or getattr(item, "volume_today", 0) or 0
            )
            positions.append(
                {
                    "code": code,
                    "amount": total,
                    "available": max(0, total - today),
                    "cost": data.get("vwap") or getattr(item, "vwap", None),
                    "market_value": data.get("market_value")
                    or getattr(item, "market_value", None),
                    "pnl": data.get("unrealized_pnl")
                    or getattr(item, "unrealized_pnl", None),
                    "raw": item,
                }
            )
        return positions

    def get_account(self):
        cash = self.context.raw.account().cash
        return {
            "total_asset": cash.get("nav"),
            "cash": cash.get("balance"),
            "available": cash.get("available", cash.get("balance")),
            "market_value": cash.get("market_value"),
            "frozen": cash.get("frozen"),
            "pnl": cash.get("pnl"),
            "raw": cash,
        }

    def _safe_code(self, code):
        try:
            return normalize_code(code)
        except Exception:
            return code

    def _matches(self, order, ref):
        return ref_matches(order, ref)


def _exchange(market):
    return {"SH": "SHSE", "SZ": "SZSE", "BJ": "BJSE"}.get(
        str(market or "SH").upper(), "SHSE"
    )


def _range_time_text(value):
    if value is None:
        return ""
    if isinstance(value, datetime.datetime):
        return value.strftime("%Y-%m-%d %H:%M:%S")
    text = str(value).strip()
    compact = text.replace("-", "").replace("/", "")
    if len(compact) >= 8 and compact[:8].isdigit() and len(text) <= 10:
        return "{0}-{1}-{2}".format(compact[:4], compact[4:6], compact[6:8])
    return text


def _state_bool(value):
    """GM 状态字段可能是 bool、0/1、'ST'/'正常'，统一为 bool/None。"""
    if value is None or value == "":
        return None
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in ("st", "*st", "true", "1", "yes"):
        return True
    if text in ("normal", "false", "0", "no", "none"):
        return False
    return bool_or_none(value)


def _is_delisted(value):
    if value is None or value == "":
        return None
    text = str(value).replace("-", "")[:8]
    if not text.isdigit():
        return bool_or_none(value)
    today = datetime.date.today().strftime("%Y%m%d")
    return text <= today

