# -*- coding: utf-8 -*-
"""QMT / 迅投适配器。"""

import datetime



class QmtAdapter(BaseAdapter):
    platform = "qmt"

    def _account_id(self):
        account = self.context.account_id()
        if not account and self.context.raw is not None:
            account = getattr(self.context.raw, "account", None)
        if not account:
            raise PlatformApiMissing("QMT account is not configured")
        return account

    def get_history(
        self, code, frequency="1d", count=1, end_time=None, fields=None, adjust=None
    ):
        code = self.normalize_code(code)
        freq = _qmt_frequency(normalize_frequency(frequency))
        fields = map_history_fields(fields, self.platform)
        end = end_time or self.context.now()
        if isinstance(end, datetime.datetime):
            fmt = "%Y%m%d" if freq in ("1d", "1w", "1M") else "%Y%m%d%H%M%S"
            end_text = end.strftime(fmt)
        else:
            end_text = str(end).replace("-", "")
        kwargs = {
            "fields": fields,
            "stock_code": [code],
            "period": freq,
            "start_time": "",
            "end_time": end_text,
            "count": int(count),
            "dividend_type": map_adjust(adjust, self.platform),
            "fill_data": True,
            "subscribe": False,
        }
        if self.context.raw is not None and hasattr(
            self.context.raw, "get_market_data_ex"
        ):
            data = self.context.raw.get_market_data_ex(**kwargs)
        else:
            data = platform_call("get_market_data_ex", **kwargs)
        return self.frame(data, code)

    def get_history_native(
        self, code, frequency="1d", count=1, end_time=None, fields=None, adjust=None
    ):
        """QMT 旧接口返回 ``{code: DataFrame}``，保持兼容。"""
        code = self.normalize_code(code)
        freq = _qmt_frequency(normalize_frequency(frequency))
        fields = map_history_fields(fields, self.platform)
        end = end_time or self.context.now()
        if isinstance(end, datetime.datetime):
            fmt = "%Y%m%d" if freq in ("1d", "1w", "1M") else "%Y%m%d%H%M%S"
            end_text = end.strftime(fmt)
        else:
            end_text = str(end).replace("-", "")
        kwargs = {
            "fields": fields,
            "stock_code": [code],
            "period": freq,
            "start_time": "",
            "end_time": end_text,
            "count": int(count),
            "dividend_type": map_adjust(adjust, self.platform),
            "fill_data": True,
            "subscribe": False,
        }
        if self.context.raw is not None and hasattr(
            self.context.raw, "get_market_data_ex"
        ):
            return self.context.raw.get_market_data_ex(**kwargs)
        return platform_call("get_market_data_ex", **kwargs)

    def get_history_range(
        self, code, frequency="1d", start_time=None, end_time=None, fields=None, adjust=None
    ):
        code = self.normalize_code(code)
        freq = _qmt_frequency(normalize_frequency(frequency))
        fields = map_history_fields(fields, self.platform)
        end = _qmt_time_text(end_time or self.context.now(), freq)
        kwargs = {
            "fields": fields,
            "stock_code": [code],
            "period": freq,
            "start_time": _qmt_time_text(start_time, freq),
            "end_time": end,
            "count": -1,
            "dividend_type": map_adjust(adjust, self.platform),
            "fill_data": True,
            "subscribe": False,
        }
        if self.context.raw is not None and hasattr(
            self.context.raw, "get_market_data_ex"
        ):
            data = self.context.raw.get_market_data_ex(**kwargs)
        else:
            data = platform_call("get_market_data_ex", **kwargs)
        return self.frame(data, code)

    def download_history(self, codes, frequency="1d", start_time=None, end_time=None):
        if not isinstance(codes, (list, tuple)):
            codes = [codes]
        period = _qmt_frequency(normalize_frequency(frequency), download=True)
        start = _qmt_time_text(start_time or "", "1d")
        end = _qmt_time_text(end_time or self.context.now(), "1d")
        for code in codes:
            platform_code = self.normalize_code(code)
            if self.context.raw is not None and hasattr(
                self.context.raw, "download_history_data"
            ):
                self.context.raw.download_history_data(
                    platform_code, period, start, end
                )
            else:
                platform_call(
                    "download_history_data", platform_code, period, start, end
                )
        return None

    def get_instruments(self, codes):
        if not isinstance(codes, (list, tuple)):
            codes = [codes]
        result = {}
        for code in codes:
            platform_code = self.normalize_code(code)
            detail = None
            try:
                if self.context.raw is not None and hasattr(
                    self.context.raw, "get_instrument_detail"
                ):
                    detail = self.context.raw.get_instrument_detail(
                        platform_code, iscomplete=True
                    )
                else:
                    detail = platform_call(
                        "get_instrument_detail", platform_code, iscomplete=True
                    )
            except Exception:
                try:
                    if self.context.raw is not None and hasattr(
                        self.context.raw, "get_instrument_detail"
                    ):
                        detail = self.context.raw.get_instrument_detail(platform_code)
                    else:
                        detail = platform_call(
                            "get_instrument_detail", platform_code
                        )
                except Exception:
                    detail = None
            canonical = normalize_code(code)
            if not detail:
                result[canonical] = build_instrument(canonical)
                continue
            expire = first_value(detail, ("ExpireDate", "expire_date"))
            is_trading = bool_or_none(
                first_value(detail, ("IsTrading", "is_trading"))
            )
            result[canonical] = build_instrument(
                canonical,
                name=first_value(
                    detail, ("InstrumentName", "instrument_name", "name")
                ),
                board=board_from_code(canonical),
                lot_size=first_value(detail, ("LotSize", "lot_size"), 100),
                tick_size=first_value(detail, ("PriceTick", "price_tick")),
                limit_up=_qmt_price(first_value(detail, ("UpStopPrice", "up_stop_price"))),
                limit_down=_qmt_price(
                    first_value(detail, ("DownStopPrice", "down_stop_price"))
                ),
                listed_date=first_value(detail, ("OpenDate", "open_date")),
                status={
                    "st": bool_or_none(first_value(detail, ("IsST", "is_st"))),
                    "suspend": None if is_trading is None else not is_trading,
                    "delisted": _delisted_from_expire(expire),
                },
            )
        return result

    def get_stock_status(self, codes, query_type="ST", date=None):
        if not isinstance(codes, (list, tuple)):
            codes = [codes]
        instruments = self.get_instruments(codes)
        key = {
            "ST": "st",
            "HALT": "suspend",
            "SUSPEND": "suspend",
            "DELISTING": "delisted",
            "DELISTED": "delisted",
        }.get(str(query_type).upper(), "st")
        return dict(
            (normalize_code(code), (instruments.get(normalize_code(code)) or {}).get("status", {}).get(key))
            for code in codes
        )

    def get_trading_dates(self, start_date=None, end_date=None, market="SH"):
        raw = self.context.raw
        start = normalize_date(start_date) or ""
        end = normalize_date(end_date) or self.context.trade_date()
        if start and start > end:
            return []
        if raw is not None and hasattr(raw, "get_trading_dates"):
            data = raw.get_trading_dates("", start, end, 10000, "1d")
        else:
            data = platform_call(
                "get_trading_dates", "", start, end, 10000, "1d"
            )
        values = []
        for item in data or []:
            value = normalize_date(item)
            if value and (not start or value >= start) and value <= end:
                values.append(value)
        return sorted(set(values))

    def get_tick_raw(self, codes, fields=None):
        if not isinstance(codes, (list, tuple)):
            codes = [codes]
        stock_code = [self.normalize_code(code) for code in codes]
        if self.context.raw is not None and hasattr(
            self.context.raw, "get_full_tick"
        ):
            return self.context.raw.get_full_tick(stock_code)
        return platform_call("get_full_tick", stock_code)

    def get_portfolio(self, field):
        try:
            account = self._account_id()
        except PlatformApiMissing:
            if self.context.is_backtest:
                print(
                    "[JINGNI_DATA_WARN] QMT backtest account unavailable; "
                    "portfolio {0}=None".format(field)
                )
                return [] if field == "positions" else None
            raise
        account_type = self.context.config.account_type or "stock"
        if field == "assets_value":
            data = platform_call(
                "get_trade_detail_data", account, account_type, "account"
            )
            return data[0].m_dBalance if data else None
        if field == "market_value":
            data = platform_call(
                "get_trade_detail_data", account, account_type, "account"
            )
            return data[0].m_dInstrumentValue if data else None
        if field == "cash":
            data = platform_call(
                "get_trade_detail_data", account, account_type, "account"
            )
            return data[0].m_dAvailable if data else None
        if field == "positions":
            return platform_call(
                "get_trade_detail_data", account, account_type, "position"
            )
        raise PlatformApiMissing("unsupported portfolio field: {0}".format(field))

    def _detail(self, kind):
        try:
            account = self._account_id()
        except PlatformApiMissing:
            if self.context.is_backtest:
                print(
                    "[JINGNI_DATA_WARN] QMT backtest account unavailable; "
                    "return empty {0}".format(kind)
                )
                return []
            raise
        account_type = self.context.config.account_type or "stock"
        rows = platform_call(
            "get_trade_detail_data", account, account_type, kind
        )
        return rows or []

    def order(self, code, side, amount, price=None, order_type="limit", remark=None):
        account = self._account_id()
        code = self.normalize_code(code)
        side = str(side).upper()
        op_type = 23 if side == SIDE_BUY else 24
        if order_type == "market":
            # 沪市市价单使用保护价类型；深市用最新价。最终参数以 QMT
            # 版本为准，V-02 冒烟时再确认。
            pr_type = 42 if str(code).endswith(".SH") else 5
        else:
            pr_type = 11
        raw = platform_call(
            "passorder",
            op_type,
            1101,
            str(account),
            code,
            pr_type,
            float(price or 0),
            int(amount),
            "JingniFlow",
            2,
            remark or "",
            self.context.raw,
        )
        return make_order(
            self.platform,
            platform_id=raw or remark,
            code=normalize_code(code),
            side=side,
            price=price,
            amount=amount,
            status="PENDING",
            status_code=raw,
            remark=remark,
            raw=raw,
        )

    def _latest_order_id(self, remark):
        """用 get_last_order_id 抢在委托列表回写前拿到柜台委托号。

        passorder 不返回委托号；仿真撮合可能在几秒内成交，等
        get_orders 可见时已经来不及撤单。这里只接受备注与本次
        remark 完全一致的最新委托，避免误撤账户里的旧单。
        """
        try:
            account = self._account_id()
        except Exception:
            return None
        account_type = str(self.context.config.account_type or "stock").lower()
        last_id = None
        try:
            last_id = platform_call(
                "get_last_order_id", account, account_type, "ORDER", "JingniFlow"
            )
        except Exception:
            try:
                last_id = platform_call(
                    "get_last_order_id", account, account_type, "ORDER"
                )
            except Exception:
                return None
        if last_id is None or str(last_id) == "-1":
            return None
        try:
            raw = platform_call(
                "get_value_by_order_id",
                str(last_id),
                account,
                account_type,
                "ORDER",
            )
        except Exception:
            return None
        raw_remark = None
        if isinstance(raw, dict):
            raw_remark = raw.get("m_strRemark") or raw.get("order_remark")
        else:
            raw_remark = getattr(raw, "m_strRemark", None) or getattr(
                raw, "order_remark", None
            )
        if not raw_remark or str(raw_remark) != str(remark):
            return None
        return str(last_id)

    def _resolve_cancel_order_id(self, order_ref):
        """把下单时的 remark 解析成 QMT 柜台真正的 m_strOrderSysID。

        QMT 的 passorder 不返回柜台委托号，order() 只能用 remark 占位。
        撤单必须用 get_trade_detail_data 里的 m_strOrderSysID，否则
        cancel(remark, ...) 会失败，委托随后会变成 EXPIRED。
        """
        raw_ref = order_ref if isinstance(order_ref, dict) else {}
        target = (
            raw_ref.get("platform_order_id")
            or raw_ref.get("id")
            or raw_ref.get("remark")
        )
        if target is None:
            return None
        target = str(target)
        # 先按 remark / 当前引用查找；找到后返回真实柜台委托号。
        try:
            orders = self.get_orders(include_finished=False)
        except Exception:
            orders = []
        for order in orders:
            if not isinstance(order, dict):
                continue
            values = (
                str(order.get("platform_order_id") or ""),
                str(order.get("remark") or ""),
            )
            if target in values:
                actual = order.get("platform_order_id")
                if actual:
                    return str(actual)
        # 如果调用方已经给了真实委托号，直接使用。
        if not target.startswith("validation-"):
            return target
        # 委托列表尚未回写时，用 get_last_order_id 抢撤单窗口。
        latest = self._latest_order_id(target)
        if latest:
            return latest
        return None

    def cancel(self, order_ref):
        order_id = self._resolve_cancel_order_id(order_ref)
        if not order_id:
            return False
        account = self._account_id()
        account_type = self.context.config.account_type or "stock"
        result = platform_call(
            "cancel", order_id, account, account_type, self.context.raw
        )
        return bool(result) if result is not None else True

    def cancel_all(self):
        count = 0
        for order in self.get_orders(include_finished=False):
            if self.cancel(order):
                count += 1
        return count

    def get_orders(self, status=None, include_finished=True):
        result = []
        for row in self._detail("order"):
            order = self._normalize_order(row)
            if status is not None and order["status"] != str(status).upper():
                continue
            if not include_finished and order["status"] in ("FILLED", "CANCELED", "REJECTED", "EXPIRED"):
                continue
            result.append(order)
        return result

    def _normalize_order(self, row):
        instrument = getattr(row, "m_strInstrumentID", "")
        exchange = getattr(row, "m_strExchangeID", "")
        try:
            code = normalize_code("{0}.{1}".format(instrument, exchange))
        except Exception:
            code = "{0}.{1}".format(instrument, exchange)
        return make_order(
            self.platform,
            platform_id=getattr(row, "m_strOrderSysID", None),
            code=code,
            side=getattr(row, "m_nDirection", None),
            price=getattr(row, "m_dLimitPrice", None),
            amount=getattr(row, "m_nVolumeTotalOriginal", None),
            filled=getattr(row, "m_nVolumeTraded", 0),
            status=getattr(row, "m_nOrderStatus", None),
            status_code=getattr(row, "m_nOrderStatus", None),
            created_at=getattr(row, "m_strInsertDate", None),
            remark=getattr(row, "m_strRemark", None),
            raw=row,
        )

    def get_trades(self, order_ref=None):
        ref = coerce_order_ref(order_ref)
        result = []
        for row in self._detail("deal"):
            order_id = getattr(row, "m_strOrderSysID", None)
            if ref is not None and isinstance(ref, dict) and ref.get("id"):
                if str(order_id) != str(ref["id"]):
                    continue
            instrument = getattr(row, "m_strInstrumentID", "")
            exchange = getattr(row, "m_strExchangeID", "")
            try:
                code = normalize_code("{0}.{1}".format(instrument, exchange))
            except Exception:
                code = "{0}.{1}".format(instrument, exchange)
            result.append(
                {
                    "code": code,
                    "order_id": order_id,
                    "price": getattr(row, "m_dPrice", None),
                    "amount": getattr(row, "m_nVolume", None),
                    "side": normalize_side(getattr(row, "m_nDirection", None)),
                    "created_at": getattr(row, "m_strTradeTime", None),
                    "raw": row,
                }
            )
        return result

    def get_positions(self):
        result = []
        for row in self._detail("position"):
            instrument = getattr(row, "m_strInstrumentID", "")
            exchange = getattr(row, "m_strExchangeID", "")
            try:
                code = normalize_code("{0}.{1}".format(instrument, exchange))
            except Exception:
                code = "{0}.{1}".format(instrument, exchange)
            result.append(
                {
                    "code": code,
                    "amount": int(getattr(row, "m_nVolume", 0) or 0),
                    "available": int(getattr(row, "m_nCanUseVolume", 0) or 0),
                    "cost": getattr(row, "m_dOpenPrice", None)
                    or getattr(row, "m_dAvgPrice", None),
                    "market_value": getattr(row, "m_dMarketValue", None),
                    "pnl": getattr(row, "m_dFloatProfit", None),
                    "raw": row,
                }
            )
        return result

    def get_account(self):
        rows = self._detail("account")
        if not rows:
            return {
                "total_asset": None,
                "cash": None,
                "available": None,
                "market_value": None,
                "frozen": None,
                "pnl": None,
                "raw": None,
            }
        row = rows[0]
        return {
            "total_asset": getattr(row, "m_dBalance", None),
            "cash": getattr(row, "m_dAvailable", None),
            "available": getattr(row, "m_dAvailable", None),
            "market_value": getattr(row, "m_dInstrumentValue", None),
            "frozen": getattr(row, "m_dFrozen", None),
            "pnl": getattr(row, "m_dFloatProfit", None),
            "raw": row,
        }


def _qmt_frequency(frequency, download=False):
    """统一频率转 QMT 周期；下载时按最小可用周期聚合。"""
    mapping = {"60m": "1h", "1M": "1mon"}
    if download:
        mapping.update(
            {
                "15m": "5m",
                "30m": "5m",
                "60m": "5m",
                "1w": "1d",
                "1M": "1d",
            }
        )
    return mapping.get(frequency, frequency)


def _qmt_time_text(value, frequency):
    if value is None or value == "":
        return ""
    if isinstance(value, datetime.datetime):
        if frequency in ("1d", "1w", "1M", "1mon"):
            return value.strftime("%Y%m%d")
        return value.strftime("%Y%m%d%H%M%S")
    text = str(value).strip()
    compact = (
        text.replace("-", "")
        .replace("/", "")
        .replace(":", "")
        .replace(" ", "")
    )
    if len(compact) >= 14:
        return compact[:14]
    if len(compact) >= 8:
        return compact[:8]
    return text


def _qmt_price(value):
    """QMT 的 UpStopPrice/DownStopPrice 以 0.001 元为单位返回。"""
    if value is None:
        return None
    try:
        price = float(value)
    except Exception:
        return value
    if abs(price) >= 1000:
        price = price / 1000.0
    return round(price, 3)


def _delisted_from_expire(value):
    if value is None or value == "" or str(value) in ("0", "19700101"):
        return None
    text = str(value).replace("-", "")[:8]
    if not text.isdigit():
        return None
    if text in ("99999999", "99991231"):
        return False
    return text <= datetime.date.today().strftime("%Y%m%d")

# ---- adapters/ptrade.py ----
# -*- coding: utf-8 -*-
"""PTrade 适配器。"""

import datetime



class PtradeAdapter(BaseAdapter):
    platform = "ptrade"

    def __init__(self, context):
        super(PtradeAdapter, self).__init__(context)
        # order() 返回策略订单 id；get_orders() 可能还没回写这笔新单。
        # 适配器每次调用都会重建，因此把待查 id 挂在长期存活的 context 上。
        pending = getattr(context, "_ptrade_pending_order_ids", None)
        if pending is None:
            pending = set()
            setattr(context, "_ptrade_pending_order_ids", pending)
        self._pending_order_ids = pending

    def _history_frame(self, data, code):
        frame = self.frame(data, code)
        if "money" in frame.columns and "amount" not in frame.columns:
            frame = frame.rename(columns={"money": "amount"})
        return frame

    def get_history(
        self, code, frequency="1d", count=1, end_time=None, fields=None, adjust=None
    ):
        code = self.normalize_code(code)
        freq = normalize_frequency(frequency)
        fields = map_history_fields(fields, self.platform)
        data = platform_call(
            "get_history",
            int(count),
            freq,
            fields,
            code,
            fq=map_adjust(adjust, self.platform),
            include=True,
        )
        frame = self._history_frame(data, code)
        if end_time is not None and not frame.empty:
            end = end_time
            if not isinstance(end, datetime.datetime):
                try:
                    end = datetime.datetime.strptime(str(end)[:10], "%Y-%m-%d")
                except Exception:
                    end = None
            if end is not None:
                try:
                    frame = frame[frame.index <= end]
                except Exception:
                    pass
        return frame

    def get_history_native(
        self, code, frequency="1d", count=1, end_time=None, fields=None, adjust=None
    ):
        return self.get_history(code, frequency, count, end_time, fields, adjust)

    def get_history_range(
        self, code, frequency="1d", start_time=None, end_time=None, fields=None, adjust=None
    ):
        code = self.normalize_code(code)
        freq = normalize_frequency(frequency)
        fields = map_history_fields(fields, self.platform)
        start = _ptrade_time_text(start_time)
        end = _ptrade_time_text(end_time)
        data = platform_call(
            "get_price",
            code,
            start_date=start,
            end_date=end,
            frequency=freq,
            fields=fields,
            fq=map_adjust(adjust, self.platform),
        )
        return self._history_frame(data, code)

    def download_history(self, codes, frequency="1d", start_time=None, end_time=None):
        # PTrade 历史行情由服务端按需提供，无本地下载接口。
        return None

    def get_instruments(self, codes):
        if not isinstance(codes, (list, tuple)):
            codes = [codes]
        platforms = [self.normalize_code(code) for code in codes]
        try:
            data = platform_call(
                "get_stock_info",
                platforms,
                field=["stock_name", "listed_date", "de_listed_date"],
            )
        except Exception:
            data = None
        result = {}
        for row in records(data):
            raw_code = first_value(row, ("symbol", "sec_id", "code", "security"))
            if raw_code is None:
                continue
            try:
                canonical = normalize_code(raw_code)
            except Exception:
                continue
            delisted = first_value(row, ("de_listed_date", "delisted_date"))
            result[canonical] = build_instrument(
                canonical,
                name=first_value(row, ("stock_name", "name", "sec_name")),
                board=board_from_code(canonical),
                lot_size=100,
                listed_date=first_value(row, ("listed_date", "list_date")),
                status={
                    "st": None,
                    "suspend": None,
                    "delisted": _is_delisted(delisted),
                },
            )
        for code in codes:
            canonical = normalize_code(code)
            if canonical not in result:
                result[canonical] = build_instrument(canonical)
        return result

    def get_stock_status(self, codes, query_type="ST", date=None):
        if not isinstance(codes, (list, tuple)):
            codes = [codes]
        result = {}
        query = str(query_type or "ST").upper()
        for code in codes:
            platform_code = self.normalize_code(code)
            try:
                data = platform_call(
                    "get_stock_status", platform_code, query, date
                )
            except Exception:
                data = None
            if isinstance(data, dict):
                if platform_code in data:
                    value = data.get(platform_code)
                elif normalize_code(code) in data:
                    value = data.get(normalize_code(code))
                elif len(data) == 1:
                    value = list(data.values())[0]
                else:
                    value = None
            else:
                value = data
            result[normalize_code(code)] = _status_bool(value)
        return result

    def get_trading_dates(self, start_date=None, end_date=None, market="SH"):
        end = normalize_date(end_date) or self.context.trade_date()
        start = normalize_date(start_date) or end
        if start > end:
            return []
        data = platform_call(
            "get_trade_days", start_date=start, end_date=end
        )
        if data is None:
            data = []
        elif hasattr(data, "tolist"):
            data = data.tolist()
        values = []
        for item in data:
            value = normalize_date(item)
            if value and start <= value <= end:
                values.append(value)
        return sorted(set(values))

    def get_tick_raw(self, codes, fields=None):
        if isinstance(codes, (list, tuple)):
            code = codes[0] if codes else None
        else:
            code = codes
        if code is None:
            return {}
        return platform_call("get_snapshot", self.normalize_code(code))

    def get_portfolio(self, field):
        try:
            portfolio = self.context.raw.portfolio
        except Exception as exc:
            raise PlatformApiMissing("PTrade portfolio failed: {0}".format(exc))
        if field == "assets_value":
            return portfolio.portfolio_value
        if field == "market_value":
            return portfolio.positions_value
        if field == "cash":
            return portfolio.cash
        if field == "positions":
            return portfolio.positions
        raise PlatformApiMissing("unsupported portfolio field: {0}".format(field))

    def order(self, code, side, amount, price=None, order_type="limit", remark=None):
        code = self.normalize_code(code)
        side = str(side).upper()
        signed_amount = int(amount) if side == SIDE_BUY else -int(amount)
        if order_type == "market":
            try:
                raw = platform_call(
                    "order_market", code, signed_amount, limit_price=price
                )
            except Exception:
                raw = platform_call("order", code, signed_amount, limit_price=price)
        else:
            raw = platform_call(
                "order", code, signed_amount, limit_price=float(price or 0)
            )
        raw_id = raw if isinstance(raw, str) else getattr(raw, "id", None)
        if raw_id:
            self._pending_order_ids.add(str(raw_id))
        return make_order(
            self.platform,
            platform_id=raw or remark,
            code=normalize_code(code),
            side=side,
            price=price,
            amount=amount,
            status="PENDING",
            status_code=raw,
            remark=remark,
            raw=raw,
        )

    def _all_order_rows(self):
        try:
            rows = platform_call("get_all_orders")
        except Exception:
            rows = []
        if isinstance(rows, dict):
            rows = rows.values()
        return list(rows or [])

    def _find_all_order(self, ref):
        code = str(ref.get("code") or "")
        amount = str(ref.get("amount") or "")
        price = str(ref.get("price") or "")
        order_id = str(ref.get("id") or "")
        for row in self._all_order_rows():
            order = self._normalize_order(row)
            if order_id and order_id in (
                str(order.get("platform_order_id") or ""),
                str(order.get("id") or ""),
            ):
                return row
            if (
                code
                and amount
                and str(order.get("code")) == code
                and str(order.get("amount")) == amount
                and (not price or str(order.get("price")) == price)
            ):
                return row
        return None

    def cancel(self, order_ref):
        ref = coerce_order_ref(order_ref)
        if not isinstance(ref, dict):
            return False
        order_id = ref.get("id") or ref.get("platform_order_id")
        if order_id:
            try:
                result = platform_call("cancel_order", order_id)
                if result is None or bool(result):
                    return True
            except Exception:
                pass
        # get_all_orders() 中的账户口径委托不在策略订单列表里，
        # 官方要求必须用 cancel_order_ex 传原始字典撤单。
        row = self._find_all_order(ref)
        if row is None:
            return False
        try:
            result = platform_call("cancel_order_ex", row)
            return result is None or bool(result)
        except Exception:
            return False

    def cancel_all(self):
        count = 0
        for order in self.get_orders(include_finished=False):
            if order.get("platform_order_id"):
                self.cancel(order)
                count += 1
        return count

    def _pending_order_rows(self):
        rows = []
        for order_id in list(self._pending_order_ids):
            try:
                data = platform_call("get_order", str(order_id))
            except Exception:
                continue
            if data is None:
                continue
            if isinstance(data, dict):
                rows.append(data)
            elif isinstance(data, (list, tuple)):
                rows.extend(data)
            else:
                rows.append(data)
        return rows

    def get_orders(self, status=None, include_finished=True):
        try:
            source = platform_call("get_orders") if include_finished else platform_call("get_open_orders")
        except Exception:
            source = {}
        rows = source.values() if isinstance(source, dict) else source or []
        all_rows = []
        if include_finished:
            # 本轮下单返回的 order id 直接走 get_order，避免 get_orders()
            # 尚未回写新单时把同代码/同数量/同价格的旧单当成新单。
            rows = self._pending_order_rows() + list(rows or [])
            try:
                all_rows = platform_call("get_all_orders")
            except Exception:
                all_rows = []
            if isinstance(all_rows, dict):
                all_rows = all_rows.values()
        result = []
        seen = set()
        for row in list(rows) + list(all_rows or []):
            order = self._normalize_order(row)
            if status is not None and order["status"] != str(status).upper():
                continue
            if not include_finished and order["status"] in (
                "FILLED",
                "CANCELED",
                "REJECTED",
                "EXPIRED",
            ):
                continue
            order_key = order.get("platform_order_id") or (
                str(order.get("code")),
                str(order.get("amount")),
                str(order.get("price")),
                str(order.get("status")),
            )
            if order_key in seen:
                continue
            seen.add(order_key)
            result.append(order)
        return result

    def _safe_code(self, code):
        try:
            return normalize_code(code)
        except Exception:
            return code

    def _normalize_order(self, row):
        data = row if isinstance(row, dict) else getattr(row, "__dict__", {})
        code = (
            data.get("security")
            or data.get("code")
            or data.get("symbol")
            or data.get("stock_code")
        )
        return make_order(
            self.platform,
            platform_id=data.get("id") or data.get("order_id") or data.get("entrust_no"),
            code=self._safe_code(code),
            side=data.get("side") or data.get("entrust_bs"),
            price=data.get("price") or data.get("limit_price"),
            amount=data.get("amount") or data.get("entrust_amount"),
            filled=data.get("filled")
            or data.get("filled_amount")
            or data.get("business_amount"),
            status=data.get("status"),
            status_code=data.get("status"),
            created_at=data.get("created_at")
            or data.get("entrust_time")
            or data.get("order_time"),
            remark=data.get("remark"),
            raw=row,
        )

    def get_trades(self, order_ref=None):
        try:
            source = platform_call("get_trades")
        except Exception:
            source = {}
        rows = source.values() if isinstance(source, dict) else source or []
        ref = coerce_order_ref(order_ref)
        result = []
        for row in rows:
            data = row if isinstance(row, dict) else getattr(row, "__dict__", {})
            order_id = data.get("order_id") or data.get("id")
            if ref is not None and isinstance(ref, dict) and ref.get("id"):
                if str(order_id) != str(ref["id"]):
                    continue
            result.append(
                {
                    "code": self._safe_code(
                        data.get("security") or data.get("code")
                    ),
                    "order_id": order_id,
                    "price": data.get("price"),
                    "amount": data.get("amount") or data.get("business_amount"),
                    "side": normalize_side(data.get("side") or data.get("entrust_bs")),
                    "created_at": data.get("created_at") or data.get("business_time"),
                    "raw": row,
                }
            )
        return result

    def get_positions(self):
        raw_positions = self.get_portfolio("positions") or {}
        if isinstance(raw_positions, dict):
            items = raw_positions.items()
        else:
            items = [(None, item) for item in raw_positions]
        result = []
        for key, item in items:
            data = item if isinstance(item, dict) else getattr(item, "__dict__", {})
            code = data.get("security") or data.get("code") or key
            try:
                code = normalize_code(code)
            except Exception:
                pass
            total = int(data.get("amount") or data.get("total_amount") or 0)
            available = int(data.get("enable_amount") or data.get("available") or 0)
            result.append(
                {
                    "code": code,
                    "amount": total,
                    "available": available,
                    "cost": data.get("cost_basis") or data.get("cost"),
                    "market_value": data.get("market_value"),
                    "pnl": data.get("pnl"),
                    "raw": item,
                }
            )
        return result

    def get_account(self):
        portfolio = self.context.raw.portfolio
        return {
            "total_asset": getattr(portfolio, "portfolio_value", None),
            "cash": getattr(portfolio, "cash", None),
            "available": getattr(portfolio, "cash", None),
            "market_value": getattr(portfolio, "positions_value", None),
            "frozen": getattr(portfolio, "frozen", None),
            "pnl": getattr(portfolio, "pnl", None),
            "raw": portfolio,
        }


def _ptrade_time_text(value):
    if value is None or value == "":
        return None
    if isinstance(value, datetime.datetime):
        return value.strftime("%Y-%m-%d %H:%M:%S")
    text = str(value).strip()
    compact = text.replace("-", "").replace("/", "").replace(":", "").replace(" ", "")
    if len(compact) >= 14:
        return "{0}-{1}-{2} {3}:{4}:{5}".format(
            compact[:4], compact[4:6], compact[6:8],
            compact[8:10], compact[10:12], compact[12:14],
        )
    if len(compact) >= 8:
        return "{0}-{1}-{2}".format(compact[:4], compact[4:6], compact[6:8])
    return text


def _is_delisted(value):
    if value is None or value == "":
        return None
    text = str(value).replace("-", "")[:8]
    if not text.isdigit():
        return None
    return text <= datetime.date.today().strftime("%Y%m%d")


def _status_bool(value):
    if value is None or value == "":
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, dict):
        for key in ("status", "is_st", "is_suspended", "is_delisted", "value"):
            if key in value:
                return _status_bool(value[key])
        return None
    text = str(value).strip().lower()
    if text in ("1", "true", "yes", "st", "halt", "delisting", "delisted"):
        return True
    if text in ("0", "false", "no", "normal"):
        return False
    return None

