# -*- coding: utf-8 -*-
"""风控 API。"""



def jingni_set_risk(config, trade_mode=None, context_data=None):
    """更新当前运行上下文的风控配置；支持 dict 或 RuntimeConfig。"""

    context = resolve_context(trade_mode or get_default_mode(), context_data)
    if isinstance(config, RuntimeConfig):
        context.config = config
    elif isinstance(config, dict):
        context.config.update(**config)
    else:
        raise TypeError("config must be dict or RuntimeConfig")
    return context.config


def jingni_check_order(
    code,
    side,
    amount,
    price=None,
    trade_mode=None,
    context_data=None,
):
    """下单前风控检查，返回 ``(ok, reason)``。"""
    context = resolve_context(trade_mode or get_default_mode(), context_data)
    adapter = get_adapter(context, context.raw)
    account = adapter.get_account()
    positions = adapter.get_positions()
    return check_order(
        context,
        normalize_code(code),
        side,
        amount,
        price,
        account=account,
        positions=positions,
    )


def jingni_calc_max_buy(
    code,
    price=None,
    trade_mode=None,
    context_data=None,
):
    """按可用资金计算最大可买股数（100 股整手）。"""
    context = resolve_context(trade_mode or get_default_mode(), context_data)
    adapter = get_adapter(context, context.raw)
    if price is None:
        frame = adapter.get_history(normalize_code(code), "1d", 1)
        series = adapter.column(frame, "close")
        if len(series) == 0:
            return 0
        price = float(series.iloc[-1])
    return calc_max_buy(adapter.get_account(), price)


def jingni_calc_max_sell(code, trade_mode=None, context_data=None):
    """按统一持仓计算最大可卖股数。"""
    context = resolve_context(trade_mode or get_default_mode(), context_data)
    adapter = get_adapter(context, context.raw)
    return calc_max_sell(adapter.get_positions(), normalize_code(code))


def jingni_kill_switch(trade_mode=None, context_data=None, cancel_orders=True):
    """启用 kill switch：撤掉未完成委托并禁止后续下单。"""
    context = resolve_context(trade_mode or get_default_mode(), context_data)
    set_kill_switch(context, True)
    adapter = get_adapter(context, context.raw)
    count = 0
    if cancel_orders:
        count = adapter.cancel_all()
    print("[JINGNI_RISK] kill switch enabled; cancelled={0}".format(count))
    return count


def jingni_log(level, msg):
    print("[{0}] {1}".format(str(level).upper(), msg))

# ---- api/instrument.py ----
# -*- coding: utf-8 -*-
"""标的元数据 API。"""



def _adapter(trade_mode, context_data):
    mode = trade_mode or get_default_mode()
    return get_adapter(mode, context_data)


def _codes(value):
    if isinstance(value, (list, tuple, set)):
        items = list(value)
    else:
        items = [value]
    if not items:
        raise ValidationError("security_codes is empty")
    return [normalize_code(item) for item in items]


def jingni_get_instrument(
    trade_mode,
    context_data,
    security_codes,
    fields=None,
):
    """I-01：批量返回标的元数据。

    返回 ``{canonical_code: {code,name,board,lot_size,tick_size,
    limit_up,limit_down,listed_date,status}}``。``fields`` 可选，用于
    只保留部分键；缺失字段由平台能力决定，不用猜测值填充。
    """
    adapter = _adapter(trade_mode, context_data)
    codes = _codes(security_codes)
    result = adapter.get_instruments(codes)
    if fields:
        wanted = (
            [str(item).strip() for item in fields.split(",") if str(item).strip()]
            if isinstance(fields, str)
            else [str(item).strip() for item in fields]
        )
        filtered = {}
        for code, item in (result or {}).items():
            filtered[code] = dict(
                (key, value) for key, value in item.items() if key in wanted
            )
        return filtered
    return result


def jingni_get_stock_status(
    trade_mode,
    context_data,
    security_codes,
    query_type="ST",
    date=None,
):
    """I-07：批量查询股票状态。

    ``query_type='ST'/'HALT'/'DELISTING'`` 返回 ``{code: bool/None}``；
    ``query_type=None`` 或 ``'ALL'`` 时一次性合并三类状态，返回
    ``{code: {'st': ..., 'suspend': ..., 'delisted': ...}}``。
    PTrade 原生支持该接口；QMT/GM 使用标的详情降级推导，无法判断时
    返回 None（不伪造 False）。
    """
    adapter = _adapter(trade_mode, context_data)
    codes = _codes(security_codes)
    query = str(query_type).upper() if query_type is not None else "ALL"
    if query == "ALL":
        result = dict((code, {}) for code in codes)
        for name, key in (
            ("ST", "st"),
            ("HALT", "suspend"),
            ("DELISTING", "delisted"),
        ):
            values = adapter.get_stock_status(codes, query_type=name, date=date)
            for code in codes:
                result[code][key] = (values or {}).get(code)
        return result
    return adapter.get_stock_status(codes, query_type=query_type, date=date)

# ---- api/calendar.py ----
# -*- coding: utf-8 -*-
"""交易日历与交易时段 API。"""

import datetime


# 交易日历在交易日内是静态数据；按 (平台, 起, 止, 市场) 缓存，避免
# 每次 handle_data 都向柜台/行情服务查询。只缓存显式日期范围。
_CALENDAR_CACHE = {}
_CALENDAR_CACHE_LIMIT = 256


def _calendar_key(trade_mode, context_data, start_date, end_date, market):
    start = normalize_date(start_date)
    end = normalize_date(end_date)
    if start is None or end is None:
        return None
    mode = trade_mode or get_default_mode()
    context_token = id(context_data) if context_data is not None else None
    return (
        str(mode).lower(),
        context_token,
        start,
        end,
        str(market or "SH").upper(),
    )


def jingni_get_trading_dates(
    trade_mode,
    context_data,
    start_date=None,
    end_date=None,
    market="SH",
):
    """I-02：返回指定范围的交易日，格式 ``YYYYMMDD``。

    三家平台差异：
    - 掘金：``get_trading_dates_by_year``，失败时降级 ``get_trading_dates``；
    - QMT：``get_trading_dates``，``count`` 必须大于 0；
    - PTrade：``get_trade_days``。
    """
    key = _calendar_key(trade_mode, context_data, start_date, end_date, market)
    if key is not None and key in _CALENDAR_CACHE:
        return list(_CALENDAR_CACHE[key])
    adapter = get_adapter(trade_mode or get_default_mode(), context_data)
    try:
        result = adapter.get_trading_dates(
            start_date=start_date, end_date=end_date, market=market
        )
    except Exception as exc:
        print("[JINGNI_DATA_ERROR] trading_dates failed: {0}".format(exc))
        return []
    if key is not None:
        if len(_CALENDAR_CACHE) >= _CALENDAR_CACHE_LIMIT:
            _CALENDAR_CACHE.clear()
        _CALENDAR_CACHE[key] = list(result or [])
    return result


def jingni_is_trading_day(trade_mode=None, context_data=None, date=None):
    """I-04：判断指定日期是否为交易日；默认使用策略当前日期。"""
    target = normalize_date(date)
    if target is None:
        try:
            target = resolve_context(
                trade_mode or get_default_mode(), context_data
            ).trade_date()
        except Exception:
            target = datetime.date.today().strftime("%Y%m%d")
    dates = jingni_get_trading_dates(
        trade_mode,
        context_data,
        start_date=target,
        end_date=target,
    )
    if dates:
        return target in dates
    # 平台日历不可用时按工作日降级；日历可用但返回空，说明是非交易日。
    try:
        adapter = get_adapter(trade_mode or get_default_mode(), context_data)
        dates = adapter.get_trading_dates(target, target)
    except Exception:
        return is_weekday(target)
    return target in (dates or [])


def jingni_is_trading_time(
    trade_mode=None,
    context_data=None,
    now=None,
    include_auction=False,
):
    """R-04：判断当前/指定时间是否处于 A 股交易时段。

    默认只包含连续竞价 09:30—11:30、13:00—15:00；
    ``include_auction=True`` 时额外包含 09:15—09:25。
    节假日优先使用平台交易日历；无平台上下文时仅按工作日降级。
    """
    if now is None:
        try:
            current = resolve_context(
                trade_mode or get_default_mode(), context_data
            ).now()
        except Exception:
            current = datetime.datetime.now()
    elif not isinstance(now, datetime.datetime):
        text = str(now).strip().replace("-", "").replace("/", "")
        parsed = None
        for fmt in ("%Y%m%d%H%M%S", "%Y%m%d%H%M", "%Y%m%d"):
            try:
                parsed = datetime.datetime.strptime(text[: len(fmt)], fmt)
                break
            except ValueError:
                continue
        current = parsed or datetime.datetime.now()
    else:
        current = now

    if not is_trading_session(current, include_auction=include_auction):
        return False
    if trade_mode is not None or context_data is not None:
        try:
            if not jingni_is_trading_day(
                trade_mode, context_data, current.date()
            ):
                return False
        except Exception:
            return is_weekday(current)
        return True
    return is_weekday(current)

# ---- api/ipo.py ----
# -*- coding: utf-8 -*-
"""打新与逆回购 API。"""

import time



def _gm_account(context):
    return context.config.account_id or ""


def _qmt_ipo_data(context, kind):
    raw = context.raw
    if raw is not None and hasattr(raw, "get_ipo_data"):
        return raw.get_ipo_data(kind)
    return platform_call("get_ipo_data", kind)


def jingni_subscribe_new_stock(
    context_data, blacklist=None, dry_run=None, trade_mode=None
):
    """申购新股；返回 ``{code: status}``。"""
    context = resolve_context(trade_mode or get_default_mode(), context_data)
    effective_dry_run = context.config.dry_run if dry_run is None else bool(dry_run)
    result = {}
    try:
        if context.platform == "goldminer":
            data = platform_call(
                "ipo_get_instruments", 1010, account_id=_gm_account(context), df=False
            )
            for item in data or []:
                code = item.get("symbol")
                if not code or (blacklist and code in blacklist):
                    continue
                if effective_dry_run:
                    result[code] = "dry_run"
                    continue
                platform_call(
                    "ipo_buy",
                    code,
                    item.get("max_vol", 0),
                    item.get("price", 0),
                    account_id=_gm_account(context),
                )
                result[code] = "submitted"
        elif context.platform == "ptrade":
            markets = (0, 1, 2, 3)
            for index, market_type in enumerate(markets):
                if effective_dry_run:
                    result[str(market_type)] = "dry_run"
                else:
                    kwargs = {"market_type": market_type}
                    if blacklist:
                        kwargs["black_stocks"] = blacklist
                    result[str(market_type)] = platform_call(
                        "ipo_stocks_order", **kwargs
                    )
                if index < len(markets) - 1:
                    time.sleep(5)
        elif context.platform == "qmt":
            data = _qmt_ipo_data(context, "STOCK")
            for code, item in (data or {}).items():
                if blacklist and code in blacklist:
                    continue
                if effective_dry_run:
                    result[code] = "dry_run"
                    continue
                account = context.account_id()
                if not account:
                    raise JingniError("QMT account is not configured")
                platform_call(
                    "passorder",
                    23,
                    1101,
                    str(account),
                    normalize_code(code, "qmt"),
                    11,
                    float(item.get("issuePrice", 0)),
                    int(item.get("maxPurchaseNum", 0)),
                    "",
                    2,
                    "",
                    context.raw,
                )
                result[code] = "submitted"
        else:
            raise ValidationError("unsupported platform: {0}".format(context.platform))
    except Exception as exc:
        print("[JINGNI_ORDER_ERROR] new stock failed: {0}".format(exc))
        result["error"] = str(exc)
    return result


def jingni_subscribe_new_bond(
    context_data, blacklist=None, dry_run=None, trade_mode=None
):
    """申购新债/可转债；返回 ``{code: status}``。"""
    context = resolve_context(trade_mode or get_default_mode(), context_data)
    effective_dry_run = context.config.dry_run if dry_run is None else bool(dry_run)
    result = {}
    try:
        if context.platform == "goldminer":
            data = platform_call(
                "ipo_get_instruments", 1030, account_id=_gm_account(context), df=False
            )
            for item in data or []:
                code = item.get("symbol")
                if not code or (blacklist and code in blacklist):
                    continue
                if effective_dry_run:
                    result[code] = "dry_run"
                    continue
                platform_call(
                    "ipo_buy",
                    code,
                    item.get("max_vol", 0),
                    item.get("price", 0),
                    account_id=_gm_account(context),
                )
                result[code] = "submitted"
        elif context.platform == "ptrade":
            if effective_dry_run:
                result["4"] = "dry_run"
            else:
                kwargs = {"market_type": 4}
                if blacklist:
                    kwargs["black_stocks"] = blacklist
                result["4"] = platform_call("ipo_stocks_order", **kwargs)
        elif context.platform == "qmt":
            data = _qmt_ipo_data(context, "BOND")
            for code, item in (data or {}).items():
                if blacklist and code in blacklist:
                    continue
                if effective_dry_run:
                    result[code] = "dry_run"
                    continue
                account = context.account_id()
                if not account:
                    raise JingniError("QMT account is not configured")
                platform_call(
                    "passorder",
                    23,
                    1101,
                    str(account),
                    normalize_code(code, "qmt"),
                    11,
                    float(item.get("issuePrice", 0)),
                    int(item.get("maxPurchaseNum", 0)),
                    "",
                    2,
                    "",
                    context.raw,
                )
                result[code] = "submitted"
        else:
            raise ValidationError("unsupported platform: {0}".format(context.platform))
    except Exception as exc:
        print("[JINGNI_ORDER_ERROR] new bond failed: {0}".format(exc))
        result["error"] = str(exc)
    return result

# ---- api/repo.py ----
# -*- coding: utf-8 -*-
"""国债逆回购 API。"""


_REPO_CODES = {
    "SH": {
        1: "204001.SH",
        2: "204002.SH",
        3: "204003.SH",
        4: "204004.SH",
        7: "204007.SH",
        14: "204014.SH",
        28: "204028.SH",
        91: "204091.SH",
        182: "204182.SH",
    },
    "SZ": {
        1: "131810.SZ",
        2: "131811.SZ",
        3: "131800.SZ",
        4: "131809.SZ",
        7: "131801.SZ",
        14: "131802.SZ",
        28: "131803.SZ",
        91: "131805.SZ",
        182: "131806.SZ",
    },
}


def _repo_code(days, market):
    market = str(market).upper()
    if market not in _REPO_CODES:
        raise ValidationError("unsupported repo market: {0}".format(market))
    code = _REPO_CODES[market].get(int(days))
    if code is None:
        raise ValidationError("unsupported repo days: {0}".format(days))
    return normalize_code(code)


def jingni_participate_reverse_repo(
    context_data,
    cash_ratio=1.0,
    reverse_repo_days=1,
    market="SH",
    min_amount=1000,
    dry_run=None,
    trade_mode=None,
):
    """参与国债逆回购；数量按 ``int(cash*ratio/1000)*10`` 计算。

    不足 ``min_amount`` 或不足 10 张时不报单，返回 None。
    """
    context = resolve_context(trade_mode or get_default_mode(), context_data)
    effective_dry_run = context.config.dry_run if dry_run is None else bool(dry_run)
    cash = jingni_portfolio(context, context.raw, "cash")
    if cash is None:
        if getattr(context, "is_backtest", False):
            print("[JINGNI_SKIP] reverse repo: cash is unavailable in backtest")
        else:
            print("[JINGNI_ORDER_ERROR] cash is unavailable")
        return None
    try:
        cash = float(cash)
        ratio = float(cash_ratio)
    except Exception:
        raise ValidationError("cash_ratio must be numeric")
    if cash <= 0 or ratio <= 0:
        return None
    code = _repo_code(reverse_repo_days, market)
    amount = int((cash * ratio) / 1000) * 10
    if amount < 10 or cash * ratio < float(min_amount):
        print("[JINGNI_REPO] cash below minimum, skip")
        return None
    price = jingni_get_field(context, context.raw, code, "1d", "close", 0)
    try:
        price = float(price)
    except Exception:
        price = 0.0
    if price <= 0:
        print("[JINGNI_REPO] repo price unavailable, skip")
        return None
    if effective_dry_run:
        print("[JINGNI_REPO] dry_run: {0} x {1} @ {2}".format(code, amount, price))
        return None
    return jingni_order_amount(
        context,
        context.raw,
        code,
        -amount,
        price,
        dry_run=False,
        remark="reverse_repo",
        check_sell_available=False,
    )

# ---- api/runtime.py ----
# -*- coding: utf-8 -*-
"""运行时 API：交易日、交易时间、初始化。"""

import datetime



def jingni_setup(trade_mode, context_data, config=None):
    """初始化并返回 RuntimeContext；不启动任何循环。"""
    mode = normalize_platform(trade_mode) or get_default_mode()
    set_default_mode(mode)
    if config is None:
        config = RuntimeConfig()
    context = resolve_context(mode, context_data, config=config)
    print(
        "[JINGNI] platform={0} mode={1} python={2}".format(
            context.platform, context.mode, _python_version()
        )
    )
    return context


def _python_version():

    return python_version_text()


def jingni_trading_dates(trade_mode, context_data, trading_dates_count):
    """返回相对当前交易日的第 N 个交易日，格式 YYYYMMDD。"""
    context = resolve_context(trade_mode, context_data)
    count = int(trading_dates_count)
    try:
        if context.platform == "goldminer":
            if count == 0:
                return context.trade_date()
            day = context.trade_date("%Y-%m-%d")
            if count > 0:
                dates = platform_call(
                    "get_next_n_trading_dates",
                    exchange="SHSE",
                    date=day,
                    n=count,
                )
                if not dates:
                    return None
                return dates[-1].strftime("%Y%m%d") if hasattr(dates[-1], "strftime") else str(dates[-1]).replace("-", "")[:8]
            dates = platform_call(
                "get_previous_n_trading_dates",
                exchange="SHSE",
                date=day,
                n=abs(count),
            )
            if not dates:
                return None
            return dates[0].strftime("%Y%m%d") if hasattr(dates[0], "strftime") else str(dates[0]).replace("-", "")[:8]
        if context.platform == "ptrade":
            value = platform_call("get_trading_day", count)
            if value is None:
                return None
            if hasattr(value, "strftime"):
                return value.strftime("%Y%m%d")
            return str(value).replace("-", "")[:8]
        if context.platform == "qmt":
            if count == 0:
                return context.trade_date()
            raw = context.raw
            if raw is None or not hasattr(raw, "get_trading_dates"):
                return None
            # QMT 官方要求 count 必须大于 0，不能用 -1。
            dates = raw.get_trading_dates("", "", "", abs(count) + 1, "1d")
            if not dates:
                return None
            current = context.trade_date()
            texts = []
            for item in dates:
                if hasattr(item, "strftime"):
                    texts.append(item.strftime("%Y%m%d"))
                else:
                    texts.append(str(item).replace("-", "")[:8])
            if current not in texts:
                return None
            index = texts.index(current)
            target = index + count
            if target < 0 or target >= len(texts):
                return None
            return texts[target]
        return None
    except Exception as exc:
        print("[JINGNI_DATA_ERROR] trading_dates failed: {0}".format(exc))
        return None


def jingni_trading_times(trade_mode, context_data):
    """返回策略时钟的 ``datetime.time``。"""
    try:
        return resolve_context(trade_mode, context_data).now().time()
    except Exception as exc:
        print("[JINGNI_DATA_ERROR] trading_times failed: {0}".format(exc))
        return None


def jingni_now(trade_mode, context_data):
    """返回平台策略时钟；回测返回回测时间。"""
    return resolve_context(trade_mode, context_data).now()


def jingni_wall_now():
    """返回本机墙钟；仅用于日志/提示，不用于回测决策。"""
    return datetime.datetime.now()


def _date_text(value):
    text = str(value).strip().replace("-", "")
    if len(text) < 8:
        raise ValueError("date must be YYYYMMDD")
    return text[:8]


def jingni_offset_trade_date(offset, date=None, trade_mode=None, context_data=None):
    """相对 date/当前交易日偏移 N 个交易日，返回 YYYYMMDD。

    掘金直接使用 ``get_previous/next_n_trading_dates`` 的 date 参数；
    QMT 从完整交易日历中定位；PTrade 只支持相对当前交易日，跨日期
    锚点返回 ``None`` 并提示，不做自然日近似。
    """
    mode = normalize_platform(trade_mode or get_default_mode())
    context = resolve_context(mode, context_data)
    count = int(offset)
    if date is None:
        return jingni_trading_dates(mode, context_data, count)
    anchor = _date_text(date)
    if count == 0:
        return anchor
    try:
        if mode == "goldminer":
            if count > 0:
                dates = platform_call(
                    "get_next_n_trading_dates",
                    exchange="SHSE",
                    date=anchor,
                    n=count,
                )
                return _format_trade_date(dates[-1]) if dates else None
            dates = platform_call(
                "get_previous_n_trading_dates",
                exchange="SHSE",
                date=anchor,
                n=abs(count),
            )
            return _format_trade_date(dates[0]) if dates else None
        if mode == "qmt":
            raw = context.raw
            if raw is None or not hasattr(raw, "get_trading_dates"):
                return None
            dates = raw.get_trading_dates("", "", "", 10000, "1d")
            texts = [_format_trade_date(item) for item in dates or []]
            if anchor not in texts:
                return None
            index = texts.index(anchor) + count
            if index < 0 or index >= len(texts):
                return None
            return texts[index]
        if anchor == context.trade_date():
            return jingni_trading_dates(mode, context_data, count)
        print("[JINGNI_DATA_ERROR] PTrade date anchor not supported: {0}".format(anchor))
        return None
    except Exception as exc:
        print("[JINGNI_DATA_ERROR] offset_trade_date failed: {0}".format(exc))
        return None


def _format_trade_date(value):
    if hasattr(value, "strftime"):
        return value.strftime("%Y%m%d")
    return str(value).replace("-", "")[:8]


def _schedule_clock(value):
    """把 ``09:31`` / ``9:31:0`` 统一成 (时, 分, 秒)。"""
    text = str(value).strip().replace("：", ":")
    parts = text.split(":")
    if len(parts) < 2:
        raise ValueError("time_rule must be HH:MM or HH:MM:SS: {0}".format(value))
    hour = int(parts[0])
    minute = int(parts[1])
    second = int(parts[2]) if len(parts) > 2 and parts[2] else 0
    if not (0 <= hour <= 23 and 0 <= minute <= 59 and 0 <= second <= 59):
        raise ValueError("time_rule out of range: {0}".format(value))
    return hour, minute, second


def _schedule_time_text(value, mode):
    hour, minute, second = _schedule_clock(value)
    if mode == "goldminer":
        return "{0:02d}:{1:02d}:{2:02d}".format(hour, minute, second)
    if mode == "qmt":
        return "{0:02d}{1:02d}{2:02d}".format(hour, minute, second)
    if mode == "ptrade":
        return "{0:02d}:{1:02d}".format(hour, minute)
    return "{0:02d}:{1:02d}:{2:02d}".format(hour, minute, second)


def jingni_schedule(
    func,
    time_rule="09:31",
    date_rule="1d",
    name=None,
    trade_mode=None,
    context_data=None,
):
    """注册平台定时任务；返回 task_id/name。

    掘金：``schedule``；QMT：``schedule_run(repeat_times=-1)``；
    PTrade：``run_daily(context, func, time)``。不创建本地线程。
    """
    mode = normalize_platform(trade_mode or get_default_mode())
    context = resolve_context(mode, context_data)
    task_name = name or getattr(func, "__name__", "jingni_task")
    try:
        clock = _schedule_time_text(time_rule, mode)
        date_text = str(date_rule or "1d").strip().lower()
        if mode == "goldminer":
            platform_call(
                "schedule",
                schedule_func=func,
                date_rule=date_text,
                time_rule=clock,
            )
            return task_name
        if mode == "qmt":
            trade_date = context.trade_date()
            raw = context.raw
            if raw is not None and hasattr(raw, "schedule_run"):
                raw.schedule_run(
                    func,
                    "{0}{1}".format(trade_date, clock),
                    -1,
                    datetime.timedelta(days=1),
                    task_name,
                )
                return task_name
            platform_call(
                "schedule_run",
                func,
                "{0}{1}".format(trade_date, clock),
                -1,
                datetime.timedelta(days=1),
                task_name,
            )
            return task_name
        if mode == "ptrade":
            platform_call("run_daily", context.raw, func, time=clock)
            return task_name
        raise ValueError("unsupported platform: {0}".format(mode))
    except Exception as exc:
        print("[JINGNI_SCHEDULE] failed: {0}".format(exc))
        return None


def jingni_run_interval(
    func,
    seconds=3,
    trade_mode=None,
    context_data=None,
):
    """R-08：按秒级间隔注册定时器。

    平台差异：
    - 掘金 ``timer`` 的 period 单位是毫秒，本函数把 seconds 转毫秒；
    - QMT ``ContextInfo.run_time`` 只接受函数名字符串，且回测无效；
    - PTrade ``run_interval`` 最小 3 秒，本函数自动下限到 3。
    返回平台定时器句柄；QMT 回测返回 None。
    """
    mode = normalize_platform(trade_mode or get_default_mode())
    context = resolve_context(mode, context_data)
    interval = max(1, int(seconds))
    try:
        if mode == "goldminer":
            return platform_call(
                "timer",
                timer_func=func,
                period=interval * 1000,
                start_delay=0,
            )
        if mode == "qmt":
            if context.is_backtest:
                print("[JINGNI_SCHEDULE] QMT run_time is not effective in backtest")
                return None
            name = func if isinstance(func, str) else getattr(func, "__name__", None)
            if not name:
                raise ValueError("QMT run_time requires a named function")
            raw = context.raw
            if raw is None or not hasattr(raw, "run_time"):
                raise ValueError("QMT ContextInfo.run_time is unavailable")
            return raw.run_time(
                name,
                "{0}nSecond".format(interval),
                "1970-01-01 00:00:00",
            )
        if mode == "ptrade":
            return platform_call(
                "run_interval", context.raw, func, seconds=max(3, interval)
            )
        raise ValueError("unsupported platform: {0}".format(mode))
    except Exception as exc:
        print("[JINGNI_SCHEDULE] run_interval failed: {0}".format(exc))
        return None

# ---- api/lifecycle.py ----
# -*- coding: utf-8 -*-
"""生命周期 API。

v0.1 的 ``jingni_main`` 是一个墙钟 ``while True`` 主循环，与三家平台的
事件模型冲突。Phase 0 起它只做初始化并立即返回，由平台事件驱动策略；
``jingni_handle_data`` 也不再内部 sleep/循环。
"""

import datetime



_ACTIVE_STRATEGY = None


def jingni_trade_strategy(trade_mode, context_data):
    """策略逻辑占位；未注册策略时使用，用户可覆盖或在此写入自己的信号。"""
    print("交易策略正在运行中，请写入你的策略逻辑")


def jingni_set_strategy(strategy):
    """注册默认策略函数；传 ``None`` 恢复占位实现。

    策略函数签名为 ``strategy(trade_mode, context_data)``。注册后，
    ``jingni_handle_data`` 每次触发都会调用它；也可以在
    ``jingni_main(..., strategy=...)`` 或 ``jingni_handle_data(...,
    strategy=...)`` 中显式传入，显式参数优先于默认注册。
    """
    global _ACTIVE_STRATEGY
    if strategy is not None and not callable(strategy):
        raise TypeError("strategy must be callable or None")
    _ACTIVE_STRATEGY = strategy
    return strategy


def jingni_get_strategy(trade_mode=None, context_data=None):
    """返回当前默认策略函数；参数保留用于兼容后续上下文扩展。"""
    return _ACTIVE_STRATEGY


def jingni_before_trading_start(trade_mode, context_data):
    print(datetime.datetime.now(), "开始运行盘前函数")
    print(datetime.datetime.now(), "结束运行盘前函数")


def _coerce_time(value):
    if value is None:
        return None
    if isinstance(value, datetime.time):
        return value
    if isinstance(value, datetime.datetime):
        return value.time()
    text = str(value).strip()
    for fmt in ("%H:%M:%S", "%H:%M"):
        try:
            return datetime.datetime.strptime(text, fmt).time()
        except Exception:
            continue
    return None


def jingni_handle_data(
    trade_mode,
    context_data,
    trade_start_time=None,
    trade_end_time=None,
    trade_seconds=None,
    strategy=None,
):
    """执行一次盘中逻辑；是否在交易时段由平台事件决定。"""
    context = resolve_context(trade_mode, context_data)
    now_time = context.now().time()
    start = _coerce_time(trade_start_time)
    end = _coerce_time(trade_end_time)
    if start is not None and now_time < start:
        return
    if end is not None and now_time > end:
        return

    strategy_func = strategy
    if strategy_func is None:
        strategy_func = _ACTIVE_STRATEGY
    if strategy_func is None:
        strategy_func = jingni_trade_strategy
    if not callable(strategy_func):
        raise TypeError("strategy must be callable")
    return strategy_func(trade_mode, context_data)


def jingni_after_trading_end(trade_mode, context_data):
    print(datetime.datetime.now(), "开始运行盘后函数")
    print(datetime.datetime.now(), "结束运行盘后函数")


def jingni_main(trade_mode, context_data, config=None, strategy=None):
    """初始化入口；不再阻塞、不再自建交易日循环。"""
    if strategy is not None:
        jingni_set_strategy(strategy)
    context = jingni_setup(trade_mode or get_default_mode(), context_data, config)
    print("[JINGNI] ready; platform events drive the strategy")
    return context

